					"type": "Call", "func": "strSplit",
					"args":   []any{w, strExpr(" ")},
					"purity": "PureCpu",
				}
			} else {
				valWord = w
			}
		} else {
			valWord = p.exprToWord(val)
		}
		body = append(body, map[string]any{
			"type": "Expr",
			"expr": map[string]any{
				"type": "Call", "func": "assocSet",
				"args":   []any{strExpr(name), strExpr(key.text), valWord},
				"purity": "Emulable",
			},
		})
		if !p.acceptPunct(",") {
			p.skipNL()
			p.expect(tPunct, "}")
			break
		}
	}
	return []map[string]any{{"type": "Block", "body": body}}
}

