package main

import (
	"bytes"
	"fmt"
	"sort"
)

// mimic shiremit.Emit: build a top-level map[string]any holding
// stmts as []any of map[string]any, then marshal.

type stmt struct {
	typ  string
	expr map[string]any
}

func marshalMap(m map[string]any) string {
	var buf bytes.Buffer
	keys := make([]string, 0, len(m))
	for k := range m {
		keys = append(keys, k)
	}
	sort.Strings(keys)
	buf.WriteByte('{')
	for i, k := range keys {
		if i > 0 {
			buf.WriteByte(',')
		}
		buf.WriteString(fmt.Sprintf("%q", k))
		buf.WriteByte(':')
		buf.WriteString(fmt.Sprintf("%v", m[k]))
	}
	buf.WriteByte('}')
	return buf.String()
}

func main() {
	innerexpr := map[string]any{"func": "exec", "args": []any{"echo", "hi"}, "type": "Call"}
	stmt := map[string]any{"type": "Expr", "expr": innerexpr}
