package main

import (
	"fmt"
)

func main() {
	inner := map[string]any{"func": "exec", "args": []any{"echo", "hi"}, "type": "Call"}
	stmt := map[string]any{"type": "Expr", "expr": inner}
	stmts := []map[string]any{stmt}
	prog := map[string]any{
		"type":             "Program",
		"contract_version": 1,
		"imports":          []any{},
		"requires":         []any{},
		"var_types":        []any{},
		"subs":             []any{},
		"stmts":            stmts,
	}
	// emulate json.Marshal by hand to exercise only the map/list serialization
	out := marshal(prog)
	fmt.Print(out)
}

func marshal(m map[string]any) string {
	keys := []string{}
	for k := range m {
		keys = append(keys, k)
	}
	// naive sort
	for i := 0; i < len(keys); i++ {
		for j := i + 1; j < len(keys); j++ {
			if keys[j] < keys[i] {
				keys[i], keys[j] = keys[j], keys[i]
			}
		}
	}
	s := "{"
	for i, k := range keys {
		if i > 0 {
			s += ","
		}
		s += `"` + k + `":` + val(m[k])
	}
	s += "}"
	return s
}

func val(v any) string {
	switch x := v.(type) {
	case string:
		return `"` + x + `"`
	case int:
		return fmt.Sprintf("%d", x)
	case []any:
		s := "["
		for i, e := range x {
			if i > 0 {
				s += ","
			}
			s += val(e)
		}
		return s + "]"
	case []map[string]any:
		s := "["
		for i, e := range x {
			if i > 0 {
				s += ","
			}
			s += mval(e)
		}
		return s + "]"
	case map[string]any:
		return mval(x)
	default:
		return "null"
	}
}

func mval(m map[string]any) string {
	keys := []string{}
	for k := range m {
		keys = append(keys, k)
	}
	for i := 0; i < len(keys); i++ {
		for j := i + 1; j < len(keys); j++ {
			if keys[j] < keys[i] {
				keys[i], keys[j] = keys[j], keys[i]
			}
		}
	}
	s := "{"
	for i, k := range keys {
		if i > 0 {
			s += ","
		}
		s += `"` + k + `":` + val(m[k])
	}
	s += "}"
	return s
}
