fn classify_array_call(
    fn_name: &str,
    args: &[Expr],
    in_fn: bool,
    stmt_idx: usize,
    top_set_arrays: &std::collections::HashSet<String>,
    acc: &mut std::collections::HashMap<String, ArrayRefs>,
) {
