        "setArray" | "setArrayAppend" | "arrayLen" | "arrayItems" | "arrayValues" | "unset" => match lit_str(first) {
            Some(n) => n,
            None => return,
        },
        "getVar" | "setVar" => {
            // Literal "name[idx]" / "name", or template `name[${i}]`
            match first {
