        if (a === '-B') opts.before = v;
        if (a === '-C') { opts.after = v; opts.before = v; }
        if (a === '-m') opts.max = v;
        continue;
      }
      const body = a.slice(1);
      // single-char flags, possibly combined (`-vi`); -H and -h override
      // each other, last one wins (GNU)
      if (body.length > 0 && [...body].every(ch => shortFlags.includes(ch))) {
        if (body.includes('v')) opts.invert = true;
        if (body.includes('i')) opts.ci = true;
        if (body.includes('n')) opts.lineNo = true;
        if (body.includes('c')) opts.count = true;
        if (body.includes('o')) opts.only = true;
        if (body.includes('q')) opts.quiet = true;
        if (body.includes('x')) opts.whole = true;
        if (body.includes('w')) opts.wholeWord = true;
        if (body.includes('b')) opts.byteOffset = true;
        if (body.includes('l')) opts.filesOnly = true;
        if (body.includes('L')) opts.filesWithout = true;
        if (body.includes('h')) { opts.noName = true; opts.forceName = false; }
        if (body.includes('H')) { opts.forceName = true; opts.noName = false; }
        if (body.includes('Z')) opts.nul = true;
        if (body.includes('r')) opts.recursive = true;
        if (body.includes('P')) opts.flavor = 'pcre'; // GNU PCRE (JS regex ≈ PCRE)
        continue;
      }
      throw new Error(`grep: unsupported flag ${a}`);
    }
    if (!patternSeen) { patterns.push(a); patternSeen = true; }
    else if (allowFiles) files.push(a);
    else throw new Error('grep: file operand');
  }
  if (patterns.length === 0) throw new Error('grep: no pattern');
  return { opts, patterns, files };
}

// Build the match regexes from the parsed patterns: BRE/ERE/fixed flavors
// (the shared breToJs/ereToJs), -x whole-line anchoring, -w GNU word
// boundaries (word constituents = [A-Za-z0-9_], the C-locale rule).
function grepRegexes(opts, patterns) {
  const srcs = patterns.map(p =>
    opts.flavor === 'fixed' ? escapeRe(p)
      : opts.flavor === 'ere' ? ereToJs(p)
      : opts.flavor === 'pcre' ? p   // JS regexes are PCRE-flavored (\d, +, (?=…))
      : breToJs(p));
  const src = srcs.map(s2 => `(?:${s2})`).join('|');
  const ci = opts.ci ? 'i' : '';
  const core = opts.wholeWord
    ? `(?<![A-Za-z0-9_])(?:${src})(?![A-Za-z0-9_])`
    : `(?:${src})`;
  // An invalid BRE/ERE (unmatched `\(`/`\)` group, a bad interval, …)
  // is a SyntaxError in JS but a runtime error in GNU grep: the caller
  // turns it into GNU's error semantics (message to fd-2, exit 2, no
  // output). `new RegExp` is the only construction point, so the try/catch
  // lives here and every call site inherits it.
  try {
    const matchRe = opts.whole ? new RegExp(`^(?:${core})$`, ci) : new RegExp(core, ci);
    const gRe = new RegExp(matchRe.source, ci + 'g');
    return { matchRe, gRe };
  } catch {
    throw new Error('grep: Unmatched ( or \\(');
  }
}

// The per-source line selection core (shared by grepText and
// builtins.grep): filters/transforms the content lines and pushes the
// formatted output lines (terminator included) to `out`. `prefix` ("" or
// "name:") precedes every line (multi-file / -r / -H forms); `byteOffset`
// prefixes the line-start (plain) or match (with -o) byte offset (GNU -b:
// LINENO:OFFSET:line with -n); `color` wraps each match in GNU's
// --color=always codes. Returns the number of SELECTED lines (the -m /
// exit-status unit).
function grepSelect(out, content, opts, matchRe, gRe, prefix, byteOffset, color) {
  const s = String(content ?? '');
  // empty input has NO lines (GNU: `printf '' | grep -v x` prints
  // nothing and exits 1 — the split of '' yields one empty line)
  if (s === '') {
    if (opts.count) out.push(prefix + '0\n');
    return 0;
  }
  const lines = s.split('\n');
  if (s.endsWith('\n')) lines.pop();
  const isMatch = (line) => matchRe.test(line);
  const lineSel = (line) => { const m = isMatch(line); return opts.invert ? !m : m; };
  const C0 = '\x1b[01;31m\x1b[K';
  const C1 = '\x1b[m\x1b[K';
  const colorize = (m) => color ? C0 + m + C1 : m;
  let selected = 0;
  if (opts.quiet) {
    for (const line of lines) {
      if (!lineSel(line)) continue;
      selected++;
      if (selected >= opts.max) break;
    }
    return selected;
  }
  if (opts.count) {
    // GNU counts SELECTED LINES (the -o flag does not change the unit;
    // -m caps the count)
    let n = 0;
    for (const line of lines) {
      if (!lineSel(line)) continue;
      selected++;
      n++;
      if (selected >= opts.max) break;
    }
    out.push(prefix + String(n) + '\n');
    return selected;
  }
  if (opts.only) {
    let lineStart = 0;
    for (let li = 0; li < lines.length; li++) {
      const line = lines[li];
      if (!lineSel(line)) { lineStart += Buffer.byteLength(line, 'utf8') + 1; continue; }
      selected++;
      const mm = [...line.matchAll(gRe)].filter(x => x[0] !== '');
      for (const x of mm) {
        out.push(prefix
          + (opts.lineNo ? `${li + 1}:` : '')
          + (byteOffset ? `${lineStart + x.index}:` : '')
          + colorize(x[0]) + '\n');
      }
      lineStart += Buffer.byteLength(line, 'utf8') + 1;
      if (selected >= opts.max) break;
    }
    return selected;
  }
  if (opts.after === 0 && opts.before === 0) {
    let lineStart = 0;
    for (let li = 0; li < lines.length; li++) {
      const line = lines[li];
      if (!lineSel(line)) { lineStart += Buffer.byteLength(line, 'utf8') + 1; continue; }
      selected++;
      const shown = color ? line.replace(gRe, (m) => m === '' ? m : C0 + m + C1) : line;
      out.push(prefix
        + (opts.lineNo ? `${li + 1}:` : '')
        + (byteOffset ? `${lineStart}:` : '')
        + shown + '\n');
      lineStart += Buffer.byteLength(line, 'utf8') + 1;
      if (selected >= opts.max) break;
    }
    return selected;
  }
  // -A/-B/-C: merge overlapping/adjacent ranges around each selected
  // line, `--` between disjoint groups (GNU). With -n, context lines
  // carry `-` and selected lines `:` (GNU).
  const sel = lines.map(lineSel);
  const ranges = [];
  for (let li = 0; li < lines.length; li++) {
    if (!sel[li]) continue;
    selected++;
    const lo = Math.max(0, li - opts.before);
    const hi = Math.min(lines.length - 1, li + opts.after);
    if (ranges.length && lo <= ranges[ranges.length - 1][1] + 1) {
      ranges[ranges.length - 1][1] = Math.max(ranges[ranges.length - 1][1], hi);
    } else {
      ranges.push([lo, hi]);
    }
    if (selected >= opts.max) break;
  }
  for (let r = 0; r < ranges.length; r++) {
    if (r > 0) out.push('--\n');
    for (let li = ranges[r][0]; li <= ranges[r][1]; li++) {
      out.push(prefix
        + (opts.lineNo ? `${li + 1}${sel[li] ? ':' : '-'}` : '')
        + lines[li] + '\n');
    }
  }
  return selected;
}

// bash `cmd &` / `(cmd) &` fork: the job is a SUBSHELL — it runs on a copy
// of the shell state; its mutations are isolated and discarded at exit
// (copy-on-write containers; nothing is restored INTO the parent because
// the parent never shares the clone). The emitted body takes the shell as
// a parameter (`sh2.background((sh2) => body)` — shir.rs lowering;
// estree-gen/astring prints the param), so the body's sh2.* calls AND its
// native-store accesses (`sh2.vars.x`, lifted-var stores) all bind the
// CLONE. Documented limitation: USER-FUNCTION bodies (`f &`) are shared
// closures whose internal `sh2` references bind the MODULE instance — a
// function's state writes still touch the parent. The worker path (a
// fresh module instance per job) is the fix for that case.
function cloneShellForJob(shell) {
  const c = Object.create(sh2); // methods via the prototype; state shadowed below
  c.vars = { ...shell.vars };
  c.arrays = new Map([...shell.arrays].map(([k, v]) => [k, [...v]]));
  c.assocNames = new Set(shell.assocNames);
  c.assocStore = new Map([...shell.assocStore].map(([k, v]) => [k, new Map(v)]));
  c.exported = new Set(shell.exported);
  c.functions = shell.functions; // shared closures — see the limitation note
  c.chans = new Map([...shell.chans].map(([k, v]) => [k, { q: [...v.q] }]));
  c._chanSeq = shell._chanSeq;
  c.lastExit = shell.lastExit;
  c.pipeStatuses = [...shell.pipeStatuses];
  c.positional = [...shell.positional];
  c.argv0 = shell.argv0;
  c.cwd = shell.cwd;
  c.fdTargets = { ...shell.fdTargets };
  c.shoptState = new Map(shell.shoptState);
  c.traps = new Map(); // bash: background (subshell) jobs reset parent traps
  c.pending = [];      // the job's own `&` children wait on the clone
  c.bgCount = 0;
  c.lastBg = 0;
  c.errexit = shell.errexit;
  c.nounset = shell.nounset;
  c.pipefail = shell.pipefail;
  c.intVars = new Set(shell.intVars);
  c.lcVars = new Set(shell.lcVars);
  c.ucVars = new Set(shell.ucVars);
  c.roVars = new Set(shell.roVars);
  c.refVars = new Map(shell.refVars);
  c.readBufs = new Map(shell.readBufs);
  c.readBufSeq = shell.readBufSeq;
  c.lang = shell.lang;
  c.execAllowlist = shell.execAllowlist;
  c.cmdVResolved = shell.cmdVResolved ? new Set(shell.cmdVResolved) : null;
  // C-frontend mem arena / wasm: shared scratch — a real fork would copy
  // the arena memory; no corpus background case touches it (worker-path
  // nicety).
  c.memArena = shell.memArena;
  c.memSeq = shell.memSeq;
  c.memElemSize = shell.memElemSize;
  c._memPos = shell._memPos;
  c._wasm = shell._wasm;
  return c;
}

export const sh2 = {
  // node:fs/promises — the native readFile/writeFile surface the emitter's
  // pure-capture lowerings (`$(cat f)`, `$(sort f)`, `$(wc -l < f)`) call
  // directly (PLAN.md §1.2's sh2.fs.* namespace; whitelisted in
  // estree_gate.pl).
  fs: fsp,

  // ── wasm "binary" registry (Plan 9) ───────────────────────────────
  // sh2runtime ships its own EXECUTABLE FORMATS: js builtins plus wasm
  // modules (posixutils-rs cores compiled to wasm — bc first). The
  // emitter dispatches exec("name") through the Plan 9 manifest; a wasm
  // call is pure CPU and SYNCHRONOUS — the *Sync loop gates stay green.
  // The loader instantiates lazily ONCE (sync WebAssembly.Module/Instance);
  // input/output strings marshal through the module's bump arena.
  _wasm: new Map(),
  _loadWasm(name) {
    if (this._wasm.has(name)) return this._wasm.get(name);
    const bytes = fs.readFileSync(new URL(`./wasm/${name}.wasm`, import.meta.url));
    const inst = new WebAssembly.Instance(new WebAssembly.Module(bytes), {});
    const { memory, alloc, reset, arena_base } = inst.exports;
    const base = arena_base();
    const enc = new TextEncoder();
    const dec = new TextDecoder();
    const put = (str) => {
      const b = enc.encode(str);
      const p = alloc(b.length);
      new Uint8Array(memory.buffer, base + p, b.length).set(b);
      return p;
    };
    const get = (packed) => {
      const p = Number(packed >> 32n);
      const l = Number(packed & 0xffffffffn);
      return l ? dec.decode(new Uint8Array(memory.buffer, base + p, l)) : '';
    };
    const api = { _reset: reset };
    // bc number core (harness/wasm/bcwasm.wasm): exact arbitrary-precision
    // arithmetic/sqrt (posixutils-rs Number(BigDecimal)) — the
    // SH2_BC_NATIVE=exact tier. Errors (negative sqrt, div-by-zero, parse)
    // return '' — bc's no-stdout-on-error.
    if (name === 'bcwasm') {
      const { bc_sqrt, bc_add, bc_sub, bc_mul, bc_div, bc_pow } = inst.exports;
      const one = (fn, a, scale = 0) => {
        const r = fn(put(a), a.length, scale);
        const out = get(r);
        reset();
        return out;
      };
      const two = (fn, a, b, scale = 0) => {
        const r = fn(put(a), a.length, put(b), b.length, scale);
        const out = get(r);
        reset();
        return out;
      };
      api.sqrt = (a, scale) => one(bc_sqrt, a, scale);
      api.add = (a, b, scale) => two(bc_add, a, b, scale);
      api.sub = (a, b, scale) => two(bc_sub, a, b, scale);
      api.mul = (a, b, scale) => two(bc_mul, a, b, scale);
      api.div = (a, b, scale) => two(bc_div, a, b, scale);
      api.pow = (a, b, scale) => two(bc_pow, a, b, scale);
    }
    this._wasm.set(name, api);
    return api;
  },
  // `sh2.bcSqrt(x, scale)` — the exact sqrt (SH2_BC_NATIVE=exact tier).
  bcSqrt(x, scale = 0) {
    return this._loadWasm('bcwasm').sqrt(String(x), scale >>> 0);
  },

  // ── state ──────────────────────────────────────────────────────────
  vars: Object.create(null), // name -> value (null-prototype object: the emitter's native store reads/writes are direct property access; no prototype pollution)
  arrays: new Map(),   // name -> array of strings (declare -a / arr=(...) / arr[i]=)
  assocNames: new Set(), // names declared `declare -A` (string-keyed)
  assocStore: new Map(), // assoc name -> Map(key, value)
  exported: new Set(),
  functions: new Map(),
  chans: new Map(),     // channel handle -> {q: []} FIFO (go-sh select/commClause; core requests go-sh-commclause / go-sh-recvstmt)
  _chanSeq: 0,
  lastExit: 0,
  pipeStatuses: [], // exit status per stage of the last pipeline (PIPESTATUS)
  positional: [],
  argv0: 'sh',
  cwd: process.cwd(),
  fdTargets: {
    0: { kind: 'stdin' },
    1: { kind: 'stdout' },
    2: { kind: 'stderr' },
  },
  shoptState: new Map(),
  traps: new Map(),       // signal -> handler string (or closure)
  pending: [],            // background promises
  execAllowlist: null,    // Set of external binaries allowed to spawn, or null = unrestricted
  cmdVResolved: null,     // Set of paths `command -v NAME` resolved (NAME was
                          // a source word — the resolved path may be exec'd)
  bgCount: 0,
  lastBg: 0,
  // `set -e` / `set -u` / `set -o pipefail` (approximated: -u is accepted
  // but not enforced; pipefail tracks the flag only)
  errexit: false,
  nounset: false,
  pipefail: false,
  // `typeset -i` / `declare -i` integer-attribute variables: later plain
  // assignments are coerced through arithmetic evaluation (bash semantics).
  intVars: new Set(),
  // `typeset -l` / `typeset -u` — lowercase / uppercase attributes
  lcVars: new Set(),
  ucVars: new Set(),
  // `typeset -n` — nameref: name -> target variable name; get/set dereference
  refVars: new Map(),
  // `typeset -r` / `readonly` — readonly attribute (tracked for `-p` output;
  // bash errors on reassignment, but no corpus test relies on the refusal).
  roVars: new Set(),
  // line buffers per read-source identity (for the `read` builtin)
  readBufs: new Map(),
  readBufSeq: 0,

  // ── init / finish ──────────────────────────────────────────────────
  _init(argv0, positional) {
    if (argv0 !== undefined) this.argv0 = argv0;
    if (positional) this.positional = [...positional];
    _installStdoutBuffer();
  },

  // Source-language mode (estree-runner.mjs sets it from the --source
  // file extension). The A1 contract is bash-shaped; constructs whose
  // semantics differ per source language (zsh arrays are 1-BASED) are
  // resolved here, at the execution boundary, where the language is
  // known. bash/posix sources never set it → unchanged behavior.
  _setLang(lang) {
    this.lang = lang;
  },

  // Security gate (see estree-runner.mjs): restrict spawned binaries to the
  // external commands that actually appear in the source script. Builtins
  // (echo, cd, read, ...) are handled natively and never spawn, so they are
  // not part of the allowlist. `names` = array of allowed external commands.
  _setAllowlist(names) {
    this.execAllowlist = names ? new Set(names) : null;
  },

  async _finish() {
    // bash's exit status = the LAST command's status (the exit builtin and
    // errexit aborts exit directly, bypassing this). The EXIT trap runs
    // with $? = that status and its own status does NOT change the exit
    // code (bash preserves it through the trap), so capture it FIRST.
    const code = this.lastExit;
    if (this.traps.has('EXIT')) {
      const h = this.traps.get('EXIT');
      if (typeof h === 'function') await h();
      else runShellString(h); // string handler: bash -c
    }
    for (const p of this.pending) { try { await p; } catch { /* bg failures ignored */ } }
    this.pending = [];
    _flushStdout();
    // The corpus gate compares the program's exit code against bash's
    // (fail-estree: "exit code (bash=N estree=M)"), so the final status
    // must be REAL. The process.exit wrapper below flushes stdout first.
    process.exit(code);
  },

  // ── variables ──────────────────────────────────────────────────────
  getVar(name) {
    const m = /^([A-Za-z_][A-Za-z0-9_]*)\[([^\]]+)\]$/.exec(name);
    if (m) {
      // PIPESTATUS — the exit statuses of the last pipeline (recorded by
      // pipeline/pipelineSync). `PIPESTATUS[i]` reads stage i; `[@]`/
      // `[*]` join all statuses.
      if (m[1] === 'PIPESTATUS') {
        if (m[2] === '@' || m[2] === '*') {
          const join = m[2] === '*' ? ((this.vars.IFS || ' ')[0] || ' ') : ' ';
          return this.pipeStatuses.map(String).join(join);
        }
        let idx;
        try { idx = evalArith(m[2], this); } catch { return ''; }
        return idx >= 0 && idx < this.pipeStatuses.length ? String(this.pipeStatuses[idx]) : '';
      }
      if (m[2] === '@' || m[2] === '*') {
        // ${x[@]} joins with spaces; ${x[*]} joins with IFS[0] — bash uses
        // IFS for `*` even when the expansion is quoted.
        const join = m[2] === '*' ? ((this.vars.IFS || ' ')[0] || ' ') : ' ';
        if (this.assocNames.has(m[1])) return this.assocValues(m[1]).join(join);
        const arr = this.arrays.get(m[1]);
        return arr ? arr.join(join) : '';
      }
      if (this.assocNames.has(m[1])) {
        const key = normAssocKey(m[2]);
        const store = this.assocStore.get(m[1]);
        return store && store.has(key) ? String(store.get(key)) : '';
      }
      const arr = this.arrays.get(m[1]);
      if (!arr) return '';
      let idx;
      try { idx = evalArith(m[2], this); } catch { return ARITH_BAD_MAGIC; } // subscript arithmetic syntax error: bash prints "syntax error in expression", skips the WHOLE command (status 1)
      return idx >= 0 && idx < arr.length ? String(arr[idx]) : '';
    }
    // `#name` — the LENGTH of a variable. Both zsh (`$#a`, `${#s}`) and
    // bash (`${#s}` unquoted) lower to getVar("#name") in A1: arrays
    // count elements, scalars count characters. (`$#` alone — the
    // positional count — is the `#` case in the switch below.) `#N`
    // (a digit) is the length of positional N's VALUE — the go-sh
    // frontend's `len(src)` over a param (`i < len(src)` lexer loops)
    // lowers to getVar("#1") and the runtime must count the caller's
    // argument, not read a never-written store var.
    const lm = /^#([A-Za-z_][A-Za-z0-9_]*|[1-9]\d*)$/.exec(name);
    if (lm) {
      const real = lm[1];
      if (this.arrays.has(real) || this.assocNames.has(real)) return String(this.arrayLen(real));
      return String(this.getVar(real).length);
    }
    switch (name) {
      case '?': return String(this.lastExit);
      case '$': return String(process.pid);
      case '#': return String(this.positional.length);
      case '@': case '*': return this.positional.join(' ');
      case '0': return this.argv0;
      case '-': return 'hB';            // shell option flags (hashall + braceexpand)
      case 'PWD': return this.cwd;
      case 'HOSTNAME': return os.hostname();
      case 'BASH_VERSION': return '5.2.15(1)-release';
      case 'BASH': return '/usr/bin/bash';
      case 'SHELL': return '/bin/bash';
      // bash 5+ specials (core request estree-20260813-233001-epochrealtime-regression):
      // $EPOCHREALTIME is seconds.microseconds (bash prints %s.%N with 6-digit
      // precision), $EPOCHSECONDS the integer second count. The emitter routes
      // the read here via getVar (never the vars/env store).
      case 'EPOCHREALTIME': return (Date.now() / 1000).toFixed(6);
      case 'EPOCHSECONDS': return String(Math.floor(Date.now() / 1000));
      default:
        if (/^[1-9]$/.test(name)) {
          const i = Number(name) - 1;
          return i < this.positional.length ? this.positional[i] : '';
        }
        if (name in this.vars) return this.vars[name];
    // nameref: `typeset -n ref=original` — reads through to the target
    if (this.refVars.has(name)) return this.getVar(this.refVars.get(name));
        // Bash: a bare array name in a scalar context yields element 0
        // (`$arr`, `${arr:-}`).
        const arr = this.arrays.get(name);
        if (arr && arr.length > 0) return String(arr[0]);
        if (this.assocNames.has(name)) {
          const store = this.assocStore.get(name);
          const first = store ? store.values().next().value : undefined;
          return first !== undefined ? String(first) : '';
        }
        return process.env[name] ?? '';
    }
  },

  // By-name form (core request frontends-assoc-arrays / py-sh-go
  // 20260806): `assocSet(name, key, value)` — the explicit A1 shape for
  // associative-array writes that frontends with hash/dict types (py
  // dicts, perl hashes, zsh `typeset -A`, bash declare -A) can emit
  // directly instead of the baked-name leak. The 2-arg form
  // (`assocSet("map[key]", v)` — the baked-name lowering of
  // `map[key]=v`) stays supported: same store, same key normalization.
  assocSet(name, key, value) {
    if (arguments.length >= 3) {
      if (!this.assocStore.has(name)) this.assocStore.set(name, new Map());
      this.assocStore.get(name).set(normAssocKey(String(key)), String(value));
      return;
    }
    const eq = name.indexOf('[');
    if (eq > 0 && name.endsWith(']')) {
      const k = normAssocKey(name.slice(eq + 1, -1));
      const base = name.slice(0, eq);
      if (!this.assocStore.has(base)) this.assocStore.set(base, new Map());
      this.assocStore.get(base).set(k, String(key));
      return;
    }
    if (!this.assocStore.has(name)) this.assocStore.set(name, new Map());
    this.assocStore.get(name).set('', String(key));
  },

  assocGet(name, key) {
    const store = this.assocStore.get(name);
    return store && store.has(normAssocKey(key)) ? String(store.get(normAssocKey(key))) : '';
  },

  assocKeys(name) {
    const store = this.assocStore.get(name);
    return store ? [...store.keys()] : [];
  },

  assocValues(name) {
    const store = this.assocStore.get(name);
    return store ? [...store.values()] : [];
  },

  setVar(name, value) {
    const m = /^([A-Za-z_][A-Za-z0-9_]*)\[([^\]]+)\]$/.exec(name);
    if (m) {
      if (this.assocNames.has(m[1])) {
        if (!this.assocStore.has(m[1])) this.assocStore.set(m[1], new Map());
        this.assocStore.get(m[1]).set(normAssocKey(m[2]), String(Array.isArray(value) ? value.join(' ') : value ?? ''));
        return true;
      }
      const arr = this.arrays.get(m[1]) ?? [];
      let idx;
      try { idx = evalArith(m[2], this); } catch { return true; } // bad subscript: bash skips the assignment
      arr[idx] = String(Array.isArray(value) ? value.join(' ') : value ?? '');
      this.arrays.set(m[1], arr);
      return true;
    }
    if (value === ARITH_BAD_MAGIC) return true; // `x=$((bad))`: the expansion aborted — bash skips the assignment
    let v = String(Array.isArray(value) ? value.join(' ') : value ?? '');
    // nameref: `ref=...` assigns the TARGET variable
    if (this.refVars.has(name)) {
      this.setVar(this.refVars.get(name), v);
      return true;
    }
    // `typeset -i` / `declare -i` attribute: the RHS is evaluated as
    // arithmetic (bash coerces `n=n+1` and `n="hello"` → 0).
    if (this.intVars.has(name)) {
      try { v = String(evalArith(v, this)); } catch { v = '0'; }
    }
    // `typeset -l` / `typeset -u` — case attributes applied on assignment
    if (this.lcVars.has(name)) v = v.toLowerCase();
    else if (this.ucVars.has(name)) v = v.toUpperCase();
    if (this.exported.has(name) || name === 'PATH') process.env[name] = v;
    this.vars[name] = v;
    return true;
  },

  _spawnEnv() {
    return { ...process.env };
  },

  // ── command execution ──────────────────────────────────────────────
  // Process substitution arguments: the emitter marks argument positions
  // that were `<(...)` with a magic prefix whose payload is the captured
  // producer stdout; materialize them to temp files (bash passes a
  // /dev/fd/N path).
  async exec(name, args = [], env = undefined) {
    if (env && typeof env === 'object') {
      // command-scoped env vars: VAR=x cmd
      for (const [k, v] of Object.entries(env)) process.env[k] = String(v);
    }
    // A bare `$@`/`$*`/`$var` command name arrives as the expanded string
    // (e.g. `sh2.exec(sh2.getVar('@'), [])` → "id -u"). bash word-splits
    // unquoted expansions, so split on IFS whitespace: first word = command,
    // the rest become leading args. An empty name is a standalone redirect
    // (`>file` with no command): no-op, status 0.
    if (typeof name === 'string') {
      const nm = name.trim();
      if (nm === '') {
        this.lastExit = 0;
        return true;
      }
      if (/\s/.test(nm)) {
        // Did the name come from a bare `$@` / `$*` expansion? If it is
        // exactly the join of the current positionals, use the positional
        // array directly — that preserves QUOTED args (`"$@"` with a
        // `'a b'` element must stay one arg) instead of word-splitting.
        if (this.positional.length > 1 && nm === this.positional.join(' ').trim()) {
          name = String(this.positional[0]);
          args = [...this.positional.slice(1).map(String), ...args];
        } else {
          const words = nm.split(/\s+/);
          name = words[0];
          args = [...words.slice(1), ...args];
        }
      }
    } else if (Array.isArray(name)) {
      // `"${cmd[@]}"` as a bare command: element 0 is the command, the
      // rest are its arguments.
      const parts = name.map(String);
      if (parts.length === 0) {
        this.lastExit = 0;
        return true;
      }
      name = parts[0];
      args = [...parts.slice(1), ...args];
    }
    // Flatten + expand args FIRST so script-defined functions receive the
    // same processed arguments as builtins/externals (GLOB_MAGIC patterns
    // expanded or kept literal, PS_MAGIC materialized, array-literal
    // placeholders dropped).
    const flat = [];
    for (const a of args) {
      if (Array.isArray(a)) flat.push(...a.map(String));
      else flat.push(String(a));
    }
    for (let i = 0; i < flat.length; i++) {
      if (flat[i] === ARRAY_LIT_MAGIC) {
        // `declare -a arr=(...)` — the arg was a side-effecting setArray
        // call (the array is already stored); drop the placeholder.
        flat.splice(i, 1);
        i--;
        continue;
      }
      if (flat[i] === BADSUB_MAGIC || flat[i] === ARITH_BAD_MAGIC) {
        // `${!prefix*[@]}` bad substitution / `$(( bad ))` arithmetic
        // error: bash skips the WHOLE command (status 1) but keeps the
        // script running.
        this.lastExit = 1;
        return false;
      }
      if (typeof flat[i] === 'string' && flat[i].startsWith(PS_MAGIC)) {
        flat[i] = materializePath(flat[i].slice(PS_MAGIC.length));
      } else if (typeof flat[i] === 'string' && flat[i].startsWith(GLOB_MAGIC)) {
        const pat = flat[i].slice(GLOB_MAGIC.length);
        const hits = globExpand(pat);
        if (hits.length > 0) flat.splice(i, 1, ...hits);
        else flat[i] = pat; // no match: bash keeps the pattern (nullglob off)
      }
    }
    const fn = this.functions.get(name);
    if (fn) {
      const saved = this.positional;
      this.positional = flat;
      let r;
      try {
        r = await fn();
      } catch (e) {
        // `return N` inside a loop body is a sh2.return Signal; the loop
        // rethrows it and the function call turns it into the return value.
        if (isSignal(e, 'RETURN')) { r = undefined; }
        else throw e;
      } finally {
        this.positional = saved;
      }
      // bash: a function's status is its `return N` value (or the last
      // command's status when it falls off the end).
      if (typeof r === 'string' && (r === '0' || r === '1')) this.lastExit = Number(r);
      else if (typeof r === 'number') this.lastExit = r;
      return this.lastExit === 0;
    }
    if (typeof builtins[name] === 'function') {
      const r = await builtins[name].call(this, flat, env);
      return r;
    }
    return await this._runProc(name, flat);
  },

  // bash reports a failed exec of an unknown command as
  // `$0: line N: cmd: command not found`, written through the CURRENT fd2
  // target (`2>&1` dups it onto stdout, `2>file` into the file, `2>&-`
  // drops it). The line number comes from the source file (argv0 is the
  // script path the harness runs): the LAST line where the command appears
  // as a word, which for the corpus's single-shot uses matches the line
  // bash reports (a loop/function re-runs report the definition/call line).
  _reportCommandNotFound(cmd) {
    if (!this._srcLines) {
      this._srcLines = [];
      try { this._srcLines = fs.readFileSync(this.argv0, 'utf8').split('\n'); } catch { /* no source */ }
    }
    let line = 0;
    if (this._srcLines.length > 0) {
      const esc = String(cmd).replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
      const re = new RegExp(`(^|[^A-Za-z0-9_./+-])${esc}([^A-Za-z0-9_]|$)`);
      for (let i = 0; i < this._srcLines.length; i++) {
        if (re.test(this._srcLines[i])) line = i + 1;
      }
    }
    const msg = line > 0
      ? `${this.argv0}: line ${line}: ${cmd}: command not found\n`
      : `${this.argv0}: ${cmd}: command not found\n`;
    emitErr(this, msg);
  },

  async _runProc(cmd, args) {
    // bash flushes its stdout buffer before fork/exec — the child may
    // write to the shared fd and must see the parent's earlier output
    // first (see the stdout-coalescing buffer above).
    _flushStdout();
    // A stray `}` / `)` that the parser recovered as a command name is a
    // bash parse error: bash executes everything BEFORE it, then aborts the
    // script (nothing after it runs) with exit status 2. Abort here with
    // the same code (the gate compares exit codes).
    if (cmd === '}' || cmd === ')') {
      process.exit(2);
    }
    if (this.execAllowlist && !this.execAllowlist.has(cmd)) {
      // A path resolved at runtime (`"$(command -v python3)"` →
      // `/usr/bin/python3`): the allowlist holds SOURCE words, so the
      // resolved path itself is never listed. The `command -v` builtin
      // records its resolutions (cmdVResolved — the name it resolved was
      // itself a source word), and a path-style command whose basename is
      // a source word is allowed too (heredoc-binary-data.sh runs
      // `"$INTERPRETER_UNDER_TEST" -E -`).
      const base = cmd.includes('/') ? cmd.slice(cmd.lastIndexOf('/') + 1) : null;
      if (!((this.cmdVResolved && this.cmdVResolved.has(cmd))
        || (base && this.execAllowlist.has(base)))) {
        // A parser-recovery artifact (e.g. a stray `}` after a subshell, or
        // the quoted tail of a mangled DQS `$(...)`): the name is not a real
        // word, so bash never runs it — no-op instead of a security error.
        // Real command names are word-ish (`a-b`, `./x`, `a.b`); anything
        // with quotes/parens/whitespace/backslashes can never be spawned as
        // a binary, so no-opping it cannot weaken the allowlist.
        if (!/^[A-Za-z0-9_.+@\/:.-]+$/.test(cmd)) {
          this.lastExit = 0;
          return true;
        }
        throw new Error(`security: command '${cmd}' not in the source allowlist`);
      }
    }
    const fd0 = this.fdTargets[0];
    const fd1 = this.fdTargets[1];
    const fd2 = this.fdTargets[2];
    // stdin from a file: hand the child an open fd instead of pre-reading the
    // whole file. Pre-reading breaks streaming consumers and BLOCKS forever on
    // character devices (ptys: `tty < /dev/pts/N`); passing the fd gives real
    // open(2) semantics for regular files and devices alike.
    const stdinFd = fd0.kind === 'file' && fd0.readMode
      ? (() => { try { return fs.openSync(expandWord(this, fd0.target), 'r'); } catch { return null; } })()
      : null;
    const stdinSrc = fd0.kind === 'string' ? fd0.content : null;

    return new Promise((resolve) => {
      let child;
      try {
        const stdio = ['pipe', 'pipe', 'pipe'];
        if (stdinFd !== null) stdio[0] = stdinFd;
        // No redirect: pass the parent's stdin fd through (bash inherits it;
        // a fresh pipe would never be written to, so `cat -` would block
        // until the spawn timeout instead of seeing EOF).
        else if (fd0.kind === 'stdin') stdio[0] = 'inherit';
        child = spawn(cmd, args, {
          cwd: this.cwd,
          env: this._spawnEnv(),
          stdio,
        });
      } catch (e) {
        if (stdinFd !== null) { try { fs.closeSync(stdinFd); } catch {} }
        if (e && e.code === 'ENOENT') this._reportCommandNotFound(cmd);
        this.lastExit = 127;
        resolve(false);
        return;
      }
      let stdoutBuf = '';
      let streamWrites = [];
      // Writing to a CLOSED fd (`>&-` dup target, or `>&N` where N was never
      // opened) fails in bash ("Bad file descriptor", exit 1) when the
      // command actually writes. The child can't be handed a closed pipe, so
      // drop the bytes AND report the failure status (a silent success would
      // flip `$(...) || { x=$?; }` chains — parse-dollar-paren-pipe.sh).
      let closedFdWrite = false;
      // Streaming child output to a file: the FIRST chunk uses the spec mode
      // (w = truncate, a = append), every later chunk must APPEND — a fresh
      // 'w' per chunk would overwrite the previous one, leaving only the last
      // chunk in the file.
      const seenFiles = new Set();
      const streamWrite = (target, d, mode) => {
        const m = seenFiles.has(target) ? 'a' : mode;
        seenFiles.add(target);
        streamWrites.push(writeFileSync(target, d, m));
      };
      const killOnCap = (buf) => {
        // Bound the capture buffer: infinite producers (`yes | head`) would
        // otherwise grow without limit until the spawn timeout.
        if (buf.length > 4_000_000) {
          try { child.kill('SIGKILL'); } catch {}
          return true;
        }
        return false;
      };
      child.stdout.on('data', (d) => {
        if (fd1.kind === 'capture') { fd1.buf += d.toString('utf8'); killOnCap(fd1.buf); }
        else if (fd1.kind === 'file') streamWrite(fd1.target, d, fd1.mode ?? 'w');
        else if (fd1.kind === 'stderr') process.stderr.write(d); // `1>&2` dup
        else if (fd1.kind === 'closed') closedFdWrite = true; // bytes lost, like bash's EBADF
        else if (fd1.kind === 'stdout') {
          // Child bytes hit the shared fd directly in bash (the child is a
          // separate writer); routing them through the coalescing buffer
          // would defer them until a later flush and REORDER them after
          // shell-buffered echo/printf output (which bash flushes only at
          // exit). Flush the pending shell strings (bash flushes before
          // fork/exec — already done in _runProc) and write the chunk now.
          _flushStdout();
          _realStdoutWrite(d);
        }
      });
      child.stderr.on('data', (d) => {
        // `2>&1` makes stderr part of the stdout target — into the capture
        // buffer inside $(...), into the file, or onto the real stdout;
        // bash routes the bytes exactly like the dup'd fd.
        if (fd2.kind === 'capture') { fd2.buf += d.toString('utf8'); killOnCap(fd2.buf); }
        else if (fd2.kind === 'file') streamWrite(fd2.target, d, fd2.mode ?? 'w');
        else if (fd2.kind === 'stdout') { _flushStdout(); _realStdoutWrite(d); } // `2>&1`
        else if (fd2.kind === 'closed') closedFdWrite = true; // bytes lost, like bash's EBADF
        else if (fd2.kind === 'stderr') process.stderr.write(d);
      });
      if (stdinSrc !== null) {
        child.stdin.on('error', () => {
          // consumer exited early (e.g. `yes | head`): the remaining write
          // gets EPIPE; that is normal shell SIGPIPE behavior, not a crash.
        });
        child.stdin.write(stdinSrc);
        child.stdin.end();
      }
      const timer = setTimeout(() => {
        try { child.kill('SIGKILL'); } catch {}
        this.lastExit = 137;
        resolve(false);
      }, SPAWN_TIMEOUT_MS);
      child.on('error', (e) => {
        clearTimeout(timer);
        if (e && e.code === 'ENOENT') this._reportCommandNotFound(cmd);
        this.lastExit = 127;
        resolve(false);
      });
      child.on('close', (code) => {
        clearTimeout(timer);
        if (stdinFd !== null) { try { fs.closeSync(stdinFd); } catch {} }
        this.lastExit = closedFdWrite ? 1 : (code ?? 127);
        resolve(this.lastExit === 0);
      });
    });
  },

  // ── sync builtin dispatch ─────────────────────────────────────────
  // Sync twin of exec()'s builtin path: the emitter lowers
  // `sh2.exec("echo", args)` (and every other builtin the runtime
  // implements synchronously — builtins.json minus async wait/exec/sleep/
  // command) to this call when no script function shadows the name.
  // Identical semantics: same arg flattening, ARRAY_LIT/BADSUB/PS/GLOB
  // magic expansion, then the SAME builtin function — minus the async
  // exec machinery (no promise per call; the whileLoopSync pattern).
  builtin(name, args = [], env = undefined) {
    // command-scoped env vars: VAR=x cmd (the emitter lowers env-carrying
    // exec calls with a sync-builtin name to this twin) — apply exactly
    // like the async exec path: into process.env, and passed to the
    // builtin fn (`IFS=: read ...` reads env.IFS).
    if (env && typeof env === 'object') {
      for (const [k, v] of Object.entries(env)) process.env[k] = String(v);
    }
    const flat = [];
    for (const a of args) {
      if (Array.isArray(a)) flat.push(...a.map(String));
      else flat.push(String(a));
    }
    for (let i = 0; i < flat.length; i++) {
      if (flat[i] === ARRAY_LIT_MAGIC) {
        // `declare -a arr=(...)` — the arg was a side-effecting setArray
        // call (the array is already stored); drop the placeholder.
        flat.splice(i, 1);
        i--;
        continue;
      }
      if (flat[i] === BADSUB_MAGIC || flat[i] === ARITH_BAD_MAGIC) {
        // `${!prefix*[@]}` bad substitution / `$(( bad ))` arithmetic
        // error: bash skips the WHOLE command (status 1) but keeps the
        // script running.
        this.lastExit = 1;
        return false;
      }
      if (typeof flat[i] === 'string' && flat[i].startsWith(PS_MAGIC)) {
        flat[i] = materializePath(flat[i].slice(PS_MAGIC.length));
      } else if (typeof flat[i] === 'string' && flat[i].startsWith(GLOB_MAGIC)) {
        const pat = flat[i].slice(GLOB_MAGIC.length);
        const hits = globExpand(pat);
        if (hits.length > 0) flat.splice(i, 1, ...hits);
        else flat[i] = pat; // no match: bash keeps the pattern (nullglob off)
      }
    }
    const fn = builtins[name];
    if (typeof fn !== 'function') {
      // Unreachable: the emitter only emits `builtin` for names in the
      // sync-builtin set. A missing impl is a runtime bug, not a script
      // error — fail loudly.
      throw new Error(`sh2.builtin: '${name}' is not a sync builtin`);
    }
    const r = fn.call(this, flat, env);
    return r;
  },

  // ── PowerShell named-block process input (v1 text approximation) ──
  // Core-request powershell-sh-go: a PowerShell `process` block runs once
  // PER PIPELINE INPUT ITEM. The v1 text approximation: input items are
  // the LINES of the program's stdin, read lazily at the first call and
  // cached. A function invoked with no pipeline input (stdin empty / at
  // EOF) runs process ZERO times — PowerShell semantics (begin once, end
  // once). Only emitted by transpiled named-block functions; no corpus
  // program calls it. The synchronous read terminates at EOF (the
  // harness runs node with a closed/empty stdin).
  pipelineInputLines() {
    if (this._psInputLines === undefined) {
      let text = '';
      try {
        const buf = Buffer.alloc(65536);
        for (;;) {
          let n;
          try {
            n = fs.readSync(0, buf, 0, buf.length, null);
          } catch {
            n = 0;
          }
          if (n <= 0) break;
          text += buf.toString('utf8', 0, n);
        }
      } catch {
        text = '';
      }
      let lines = text.split('\n');
      if (lines.length > 0 && lines[lines.length - 1] === '') lines.pop();
      this._psInputLines = lines;
    }
    return this._psInputLines;
  },

  // ── sync function dispatch ────────────────────────────────────────
  // The `f args...` script-function call lift (see src/shir.rs
  // fn_call_sync_set): the SYNC twin of exec()'s function-dispatch path —
  // identical arg flattening + ARRAY_LIT/BADSUB/PS/GLOB magic expansion,
  // positional save/restore, RETURN-signal unwinding and lastExit
  // recording (the exact exec body for a defined function) — minus the
  // async exec machinery: no promise per call, no builtin/external
  // fallback dispatch. The emitter only emits this for functions whose
  // every definition body AND the call-site args are provably await-free
  // (the define arrow is emitted non-async for them), so `fn()` returns
  // the value directly. A target that is missing at call time (a
  // conditional/guarded definition that never ran) falls back the way the
  // async exec path would without spawning: builtin, else command-not-
  // found with status 127.
  fnCall(name, args = []) {
    const flat = [];
    for (const a of args) {
      if (Array.isArray(a)) flat.push(...a.map(String));
      else flat.push(String(a));
    }
    for (let i = 0; i < flat.length; i++) {
      if (flat[i] === ARRAY_LIT_MAGIC) {
        flat.splice(i, 1);
        i--;
        continue;
      }
      if (flat[i] === BADSUB_MAGIC || flat[i] === ARITH_BAD_MAGIC) {
        this.lastExit = 1;
        return false;
      }
      if (typeof flat[i] === 'string' && flat[i].startsWith(PS_MAGIC)) {
        flat[i] = materializePath(flat[i].slice(PS_MAGIC.length));
      } else if (typeof flat[i] === 'string' && flat[i].startsWith(GLOB_MAGIC)) {
        const pat = flat[i].slice(GLOB_MAGIC.length);
        const hits = globExpand(pat);
        if (hits.length > 0) flat.splice(i, 1, ...hits);
        else flat[i] = pat; // no match: bash keeps the pattern (nullglob off)
      }
    }
    const fn = this.functions.get(name);
    if (typeof fn !== 'function') {
      // The definition never ran (guarded/conditional define, or a call
      // before the define). bash falls back to the builtin, then to
      // command-not-found (status 127) — replicate without the spawn.
      if (typeof builtins[name] === 'function') {
        return builtins[name].call(this, flat);
      }
      this._reportCommandNotFound(name);
      this.lastExit = 127;
      return false;
    }
    const saved = this.positional;
    this.positional = flat;
    let r;
    try {
      // `fn(...flat)` — the flat args double as the JS params of a
      // define'd `Lambda` arrow (core request py-sh-go-lambdef); the
      // zero-param shell-function arrows ignore them.
      r = fn(...flat);
    } catch (e) {
      // `return N` inside a loop body is a sh2.return Signal; the loop
      // rethrows it and the function call turns it into the return value.
      if (isSignal(e, 'RETURN')) r = undefined;
      else throw e;
    } finally {
      this.positional = saved;
    }
    // bash: a function's status is its `return N` value (or the last
    // command's status when it falls off the end).
    if (typeof r === 'string' && (r === '0' || r === '1')) this.lastExit = Number(r);
    else if (typeof r === 'number') this.lastExit = r;
    return this.lastExit === 0;
  },

  // ── VALUE-returning function dispatch (the C frontend) ──────────
  // A1 Call("fnValue", [name, [args...]]) — emitted by c-sh-go for a
  // user function call in a VALUE position (printf arg, assign RHS).
  // sh2.fnCall is the SHELL function call: its value channel is the
  // STATUS (boolean). A C `return e` carries a VALUE, so the C frontend
  // dispatches through fnValue instead: same positional save/restore
  // and RETURN-signal handling as fnCall, but the define-arrow's return
  // value (the C `return e` stays a native JS return inside the arrow —
  // see estree.rs fix_stmt) comes back to the caller. Caller-side
  // consumers (printf %d, the store assign) coerce it.
  fnValue(name, args = []) {
    const flat = [];
    for (const a of args) {
      if (Array.isArray(a)) flat.push(...a.map(String));
      else flat.push(String(a));
    }
    for (let i = 0; i < flat.length; i++) {
      if (flat[i] === ARRAY_LIT_MAGIC) {
        flat.splice(i, 1);
        i--;
        continue;
      }
      if (flat[i] === BADSUB_MAGIC || flat[i] === ARITH_BAD_MAGIC) {
        this.lastExit = 1;
        return '0';
      }
      if (typeof flat[i] === 'string' && flat[i].startsWith(PS_MAGIC)) {
        flat[i] = materializePath(flat[i].slice(PS_MAGIC.length));
      } else if (typeof flat[i] === 'string' && flat[i].startsWith(GLOB_MAGIC)) {
        const pat = flat[i].slice(GLOB_MAGIC.length);
        const hits = globExpand(pat);
        if (hits.length > 0) flat.splice(i, 1, ...hits);
        else flat[i] = pat; // no match: bash keeps the pattern (nullglob off)
      }
    }
    const fn = this.functions.get(name);
    if (typeof fn !== 'function') {
      // undefined target: replicate fnCall's fallback chain (builtin,
      // then command-not-found 127) and yield the C-ish '0' (the
      // store is string-typed; the caller coerces).
      if (typeof builtins[name] === 'function') {
        return builtins[name].call(this, flat);
      }
      this._reportCommandNotFound(name);
      this.lastExit = 127;
      return '0';
    }
    const saved = this.positional;
    this.positional = flat;
    let r;
    try {
      // `fn(...flat)` — see fnCall (lambda params).
      r = fn(...flat);
    } catch (e) {
      // `return N` inside a loop body is a sh2.return Signal; the loop
      // rethrows it and the function call turns it into the value.
      if (isSignal(e, 'RETURN')) r = undefined;
      else throw e;
    } finally {
      this.positional = saved;
    }
    return r;
  },

  // `ternary(cond, a, b)` — the C frontend's `cond ? a : b` lowering:
  // the cond is the frontend's test-string evaluated with the SAME
  // native-first policy as the A1 `test` call (the core's "ternary" arm
  // lowers it via try_native_test, falling back to sh2.test), the
  // branches are the already-lowered A1 values — pure, so eager
  // evaluation is sound for the pure-expression subset.
  ternary(cond, a, b) {
    return cond ? a : b;
  },

  // ── direct native function calls ─────────────────────────────────
  // The emitter lowers provably-positional-free sync-function calls to
  // direct JS calls on module-level `let f` bindings (src/shir.rs
  // native_direct_fn_set): `sh2.callDirect(f)` (no args) or
  // `sh2.callDirect(f, [args])`. Replicates the sync fnCall's status
  // semantics EXACTLY — the RETURN-signal catch (sh2.return sets lastExit
  // then throws), the numeric/`'0'`/`'1'` return-value recording, the
  // final `lastExit === 0` boolean — minus the arg flattening, magic
  // expansion, Map lookup and positional save/restore (the analysis
  // guarantees the body never reads/writes positionals and the call-site
  // args are magic-free). Args are evaluated EAGERLY at the call site
  // (the array literal), exactly the fnCall argument order.
  // The native-direct function call (src/shir.rs DIRECT_FN_CALLS): the
  // emitter passes the module binding `let __fn_f` (init null — the
  // define reassigns it to the real arrow) plus the call-site args, and
  // replicates the sync fnCall's status semantics EXACTLY — the
  // RETURN-signal catch (sh2.return sets lastExit then throws), the
  // numeric/`'0'`/`'1'` return-value recording, the final
  // `lastExit === 0` boolean — minus the arg flattening, magic expansion,
  // Map lookup and positional save/restore (the analysis guarantees the
  // body never reads/writes positionals and the call-site args are
  // magic-free). Args are evaluated EAGERLY at the call site (the array
  // literal), exactly the fnCall argument order. A null binding (the
  // define never ran — guarded/conditional definitions) falls back the
  // way fnCall would: builtin, else command-not-found with status 127.
  callDirect(name, fn, args) {
    if (typeof fn !== 'function') return this.callUndefined(name, args ?? []);
    let r;
    try {
      r = args ? fn(...args) : fn();
    } catch (e) {
      if (isSignal(e, 'RETURN')) return this.lastExit === 0;
      throw e;
    }
    if (typeof r === 'number') this.lastExit = r;
    else if (typeof r === 'string' && (r === '0' || r === '1')) this.lastExit = Number(r);
    return this.lastExit === 0;
  },
  // The fallback binding of a native-direct function (`let f =
  // (...__sh2_args) => sh2.callUndefined("f", __sh2_args)`) — the exact
  // tail of fnCall's undefined-target path: builtin fallback (with the
  // flattened args), else command-not-found + status 127.
  callUndefined(name, args) {
    if (typeof builtins[name] === 'function') {
      return builtins[name].call(this, args.map(String));
    }
    this._reportCommandNotFound(name);
    this.lastExit = 127;
    return false;
  },

  // `testArith(s)` — a C condition that needs ARITHMETIC (bitwise /
  // shift / mod inside a test — the bash `test` grammar is
  // comparison-only; the c-sh-go frontend routes such conditions here,
  // see condCall). The string is a bash-arith expression
  // (`$(( ))` semantics — evalArith evaluates + - * / % ** << >> & | ^
  // comparisons && || ! ~); its numeric truth is the condition.
  testArith(s) {
    let v;
    try { v = evalArith(String(s), this); } catch { v = 0; }
    this.lastExit = v ? 0 : 1;
    return v !== 0;
  },

  // ── test expressions ───────────────────────────────────────────────
  test(expr, style) {
    try {
      // `[[ ]]` (the emitter tags the call with a second `"[["` arg):
      // bash does NOT word-split in `[[ ]]` — an unquoted expansion that
      // evaluates EMPTY stays an empty OPERAND (`[[ -n $(empty) ]]` is
      // FALSE — the dangling `-n` is a syntax error only when literally
      // present). In `[ ]` the empty vanishes (word-splitting) and a
      // lone `-n` becomes a non-empty string test (true) — the two must
      // differ.
      const tokens = tokenizeTest(expr, style === '[[');
      const ast = parseTest(tokens);
      const r = evalTest(ast, this);
      this.lastExit = r ? 0 : 1;
      return r;
    } catch (e) {
      throw new Error(`sh2.test: cannot evaluate ${JSON.stringify(expr)}: ${e.message}`);
    }
  },

  // `[ -f x ]` family — the emitter's native file-test lowering
  // (src/shir.rs try_native_file_test): evalUnary's exact bash semantics
  // (empty-arg rule, cwd resolution, accessSync `-r`/`-w`/`-x`, lstatSync
  // + the missing-path catch table, `-t` constant false) as a direct
  // flag+path call — no test-string tokenize/parse, no builtin dispatch.
  // SYNC (like every builtin — the sync I/O lives in the runtime, not the
  // emitted code), so a file test keeps its enclosing loop on the *Sync
  // gates (forLoopSync/whileLoopSync): the async `sh2.fs.lstat/access`
  // chains this replaces were the last await in otherwise-sync bodies.
  // Pure value: the EMITTER records the status (`$?`) via its
  // native-test lastExit protocol (see src/shir.rs native_test_statused)
  // — the helper must not write lastExit itself or the protocol's
  // single-eval scratch would double-write.
  fileTest(flag, arg) {
    return evalUnary(flag, arg, this);
  },

  // ── command substitution ───────────────────────────────────────────
  async capture(fn) {
    const saved = this.fdTargets[1];
    const savedStart = this.captureStart;
    this.fdTargets[1] = { kind: 'capture', buf: '' };
    this.captureStart = Date.now();
    try {
      await fn();
      // bash command substitution strips NUL bytes from the captured output.
      return this.fdTargets[1].buf.replace(/\u0000/g, '').replace(/\n+$/, '');
    } finally {
      this.fdTargets[1] = saved;
      this.captureStart = savedStart;
    }
  },

  // `line(s, i)` — the i-th line of a captured multi-value return (the
  // c-sh-go out-param transform: a multi-write function echoes one value
  // per line; the caller captures and destructures via line(t, 0),
  // line(t, 1), ... — multi-return A1, core request c-multi-return).
  line(s, i) {
    const parts = String(s).split('\n');
    return parts[Number(i) || 0] ?? '';
  },

  // Sync twin of capture() for PROVABLY-AWAIT-FREE bodies (the emitter's
  // verdict: no AwaitExpression in the lowered body — the same scan the
  // *Sync loops use, src/shir.rs). Identical semantics — the fd-1 capture
  // swap, NUL strip, trailing-newline strip, captureStart bound — minus
  // the per-call promise/microtask machinery (the whileLoopSync pattern).
  // An await-free body runs to completion synchronously and cannot yield,
  // so the microtask interleaving of background jobs matches the async
  // form's post-await continuation; a background job's fd-1 writes go to
  // the REAL sink, never into a live capture buffer (closer to bash's
  // fork than the async form's late-restore window).
  captureSync(fn) {
    const saved = this.fdTargets[1];
    const savedStart = this.captureStart;
    this.fdTargets[1] = { kind: 'capture', buf: '' };
    this.captureStart = Date.now();
    try {
      fn();
      return this.fdTargets[1].buf.replace(/\u0000/g, '').replace(/\n+$/, '');
    } finally {
      this.fdTargets[1] = saved;
      this.captureStart = savedStart;
    }
  },

  // The capture post-processing (NUL strip + trailing-newline strip) for
  // the emitter's native capture lifts (`$(echo X | tr a-z A-Z)` →
  // `sh2.trimCapture(String(X).toUpperCase())`): a pure string transform
  // replaces the whole capture+spawn machinery, and this helper applies
  // exactly the strips capture() would.
  trimCapture(s) {
    return String(s ?? '').replace(/\u0000/g, '').replace(/\n+$/, '');
  },

  // The `$(dirname X)` / `$(basename X)` pure-capture lifts: the exact
  // string the builtins.dirname/basename would emit for a single path arg
  // (minus the trailing newline the capture strips). Mirrors the builtins'
  // trailing-slash handling (GNU dirname/basename semantics).
  dirname(x) {
    let s = String(x ?? '');
    while (s.endsWith('/') && s.length > 1) s = s.slice(0, -1);
    const idx = s.lastIndexOf('/');
    return idx < 0 ? '.' : (idx === 0 ? '/' : s.slice(0, idx));
  },

  // `$(mktemp TPL)` — value-returning twin of builtins.mktemp (the
  // emitter's capture lift for the FILE form; `-d` has the native
  // fs.mkdtemp path). Creates the unique file and RETURNS its path —
  // the exact value the builtin would emit minus the trailing newline —
  // with the same lastExit protocol (0 + path, 1 + "" on a too-few-X
  // template / exhausted retries). Mirrors builtins.mktemp's arg parse
  // (flags -d/-u/-t/--suffix; the FIRST positional is the template),
  // the trailing-X-run rule (≥3 X's), the random-suffix retry loop and
  // the error messages.
  mktempValue(args) {
    let isDir = false, dry = false, template = null, suffix = '';
    const pos = [];
    for (let i = 0; i < args.length; i++) {
      const a = String(args[i]);
      if (a === '-d') isDir = true;
      else if (a === '-u') dry = true;
      else if (a === '-t' && pos.length === 0) template = path.join(os.tmpdir(), 'tmp.XXXXXXXXXX');
      else if (a === '--suffix') suffix = String(args[++i] ?? '');
      else if (a.startsWith('--suffix=')) suffix = a.slice(9);
      else if (a.startsWith('-')) { /* other flags: best-effort */ }
      else pos.push(a);
    }
    if (pos.length === 1) template = pos[0];
    const tpl = template ?? path.join(os.tmpdir(), 'tmp.XXXXXXXXXX');
    const xRun = tpl.match(/X+$/);
    if (!xRun || xRun[0].length < 3) {
      emitErr(this, `mktemp: too few X's in template \`${tpl}'\n`);
      this.lastExit = 1;
      return '';
    }
    if (suffix.length > xRun[0].length) {
      emitErr(this, `mktemp: suffix is too long (no room for it in the template)\n`);
      this.lastExit = 1;
      return '';
    }
    const base = tpl.slice(0, tpl.length - xRun[0].length);
    const chars = 'abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789';
    const rand = (n) => Array.from({ length: n }, () => chars[Math.floor(Math.random() * chars.length)]).join('');
    for (let attempt = 0; attempt < 100; attempt++) {
      const name = base + rand(xRun[0].length - suffix.length) + suffix;
      try {
        if (dry) { this.lastExit = 0; return name; }
        if (isDir) fs.mkdirSync(name);
        else fs.closeSync(fs.openSync(name, 'wx'));
        this.lastExit = 0;
        return name;
      } catch (e) {
        if (e && e.code === 'EEXIST') continue; // collision — retry
        emitErr(this, `mktemp: cannot create ${isDir ? 'directory' : 'file'} \`${name}': ${e?.message ?? e}\n`);
        this.lastExit = 1;
        return '';
      }
    }
    emitErr(this, `mktemp: failed to create ${isDir ? 'directory' : 'file'} via template \`${tpl}'\n`);
    this.lastExit = 1;
    return '';
  },
  basename(x) {
    let s = String(x ?? '');
    while (s.endsWith('/') && s.length > 1) s = s.slice(0, -1);
    const idx = s.lastIndexOf('/');
    return idx < 0 ? s : (idx === 0 ? s : s.slice(idx + 1));
  },

  // The `$(uname …)` / `$(date …)` / `$(readlink …)` pure-capture lifts:
  // value-returning twins of the sync builtins — the builtin's emitted
  // output minus the trailing newline the capture strips (exactly what
  // `await sh2.capture(() => sh2.builtin(name, args))` would yield, with
  // no capture machinery and no per-call promise). The builtin's
  // lastExit is intentionally not recorded (the value is the contract;
  // a failing readlink yields "" — the same string the capture path
  // would produce).
  uname(...flags) {
    const saved = this.fdTargets[1];
    this.fdTargets[1] = { kind: 'capture', buf: '' };
    builtins.uname.call(this, flags);
    const out = this.fdTargets[1].buf.replace(/\n$/, '');
    this.fdTargets[1] = saved;
    return out;
  },
  date(...args) {
    const saved = this.fdTargets[1];
    this.fdTargets[1] = { kind: 'capture', buf: '' };
    builtins.date.call(this, args);
    const out = this.fdTargets[1].buf.replace(/\n$/, '');
    this.fdTargets[1] = saved;
    return out;
  },
  readlink(...args) {
    const saved = this.fdTargets[1];
    this.fdTargets[1] = { kind: 'capture', buf: '' };
    builtins.readlink.call(this, args);
    const out = this.fdTargets[1].buf.replace(/\n$/, '');
    this.fdTargets[1] = saved;
    return out;
  },
  whoami() {
    const saved = this.fdTargets[1];
    this.fdTargets[1] = { kind: 'capture', buf: '' };
    builtins.whoami.call(this, []);
    const out = this.fdTargets[1].buf.replace(/\n$/, '');
    this.fdTargets[1] = saved;
    return out;
  },
  hostname(...args) {
    const saved = this.fdTargets[1];
    this.fdTargets[1] = { kind: 'capture', buf: '' };
    builtins.hostname.call(this, args);
    const out = this.fdTargets[1].buf.replace(/\n$/, '');
    this.fdTargets[1] = saved;
    return out;
  },

  // Unquoted $(...) — bash word-splits the captured output on IFS.
  async captureWords(fn) {
    const out = await this.capture(fn);
    return out.split(/\s+/).filter(w => w.length > 0);
  },

  // Sync twin of captureWords (see captureSync): the await-free verdict
  // makes the capture body run synchronously, so the split applies to the
  // already-complete buffer.
  captureWordsSync(fn) {
    const out = this.captureSync(fn);
    return out.split(/\s+/).filter(w => w.length > 0);
  },

  // Unquoted $var / ${...} in exec-arg position.
  fieldSplit(v) {
    return String(v ?? '').split(/\s+/).filter(w => w.length > 0);
  },

  // Native $(mktemp [flags] TEMPLATE) lift.
  mktemp(isDir, tpl) {
    const t = String(tpl ?? '/tmp/tmp.XXXXXX');
    const m = /X+$/.exec(t);
    if (!m) throw new Error(`mktemp: template "${t}" must end in X`);
    const prefix = t.slice(0, t.length - m[0].length);
    const rand = (n) => {
      let s = '';
      while (s.length < n) s += crypto.randomBytes(n).toString('hex');
      return s.slice(0, n);
    };
    let p;
    do { p = prefix + rand(m[0].length); } while (fs.existsSync(p));
    if (isDir) fs.mkdirSync(p, { mode: 0o700 });
    else fs.closeSync(fs.openSync(p, 'w', 0o600));
    return p;
  },

  // The `split` marker on UNQUOTED expansions (for-iters `for w in $y`,
  // exec args `set -- $y`): bash field-splits on default-IFS whitespace
  // and drops empty fields — an empty/unset variable yields ZERO fields
  // (zero iterations / zero args). The emitter lowers split(x) to the
  // native `String(x).split(/\s+/).filter(w => w.length > 0)` (no
  // dispatch); this helper is the fallback for the (currently unreachable)
  // awaited-arg case, mirroring captureWords' split exactly. In zsh mode
  // unquoted expansions NEVER field-split (SH_WORD_SPLIT is off by
  // default): the whole value is one field — even when empty (zsh
  // iterates once with the empty string; bash iterates zero times).
  split(s) {
    if (this.lang === 'zsh') {
      // zsh never field-splits unquoted expansions (SH_WORD_SPLIT off),
      // so a SCALAR stays one field — even when empty. An ARRAY value
      // (the `(f)`/`(s:)` flag splits) is already word-separated: zsh
      // unquoted array expansion DROPS empty elements (`printf '<%s>\n'
      // ${(f)x}` with a trailing-newline value prints no empty line;
      // `${(f)unset}` prints one `<>` — an empty ARRAY of zero words).
      if (Array.isArray(s)) return s.filter(w => w !== '');
      return [String(s ?? '')];
    }
    const text = String(s ?? '');
    // Custom IFS (core request frontends-ifs 20260806): a NON-whitespace
    // IFS (`IFS=, for w in $x` / `IFS=: read`) splits on the separator
    // chars and KEEPS empty fields between adjacent separators (bash
    // field semantics — same rule as the read builtin below). The
    // default / whitespace-only IFS keeps the historic whitespace
    // collapse (byte-identical corpus behavior).
    const ifs = this.vars.IFS;
    if (ifs === undefined || ifs === null || /^[ \t\n]+$/.test(String(ifs))) {
      return text.split(/\s+/).filter(w => w.length > 0);
    }
    const esc = String(ifs).replace(/[\]^$.*+?()[{}|\\]/g, '\\$&');
    return text.split(new RegExp('[' + esc + ']'));
  },

  // ── redirects ──────────────────────────────────────────────────────
  // The fd-spec install/restore logic shared by redirect + redirectSync.
  // `saved` is the pre-redirect fd table (fd-duplication `&N` targets
  // resolve against it — bash fds share the underlying file description,
  // so a duplicate must alias the SAME target object). `check` enables
  // the missing-file error path (the live install; the persistent-restore
  // pass installs without checking — a vanished file must not flip the
  // status). Returns false when a read-mode target is missing (the
  // caller returns that as the redirect's status, exactly the async
  // original's early return).
  _applyRedirectSpecs(specs, saved, check) {
    for (const s of specs) {
      const fd = s.fd ?? (s.mode === 'r' ? 0 : 1);
      if (s.mode === 'unsupported') throw new Error('redirect: process substitution not yet supported');
      // `2>&1` / `3<&0` — duplicate another fd (target is "&N"). Share
      // the SAME target object (bash fds share the underlying file
      // description): a shallow copy would lose capture-buffer writes
      // (`$(cmd 2>&1)` must capture stderr into the same buf).
      if (/^&\d+$/.test(String(s.target ?? ''))) {
        const src = Number(String(s.target).slice(1));
        this.fdTargets[fd] = saved[src] ? saved[src] : { kind: 'closed' };
        continue;
      }
      // `>&-` / `<&-` — close an fd. The parser strips the `&` (`4>&-`
      // arrives as target "-"), so accept the bare form too (a file named
      // "-" does not occur in the corpus).
      if (String(s.target ?? '') === '&-' || String(s.target ?? '') === '-') {
        this.fdTargets[fd] = { kind: 'closed' };
        continue;
      }
      if (s.mode === 'heredoc' || s.mode === 'heredoc-tabs' || s.mode === 'herestring') {
        let content = String(s.target ?? '');
        // bash appends a newline to herestrings (`<<< x` feeds "x\n").
        if (s.mode === 'herestring') content += '\n';
        if (s.mode === 'heredoc' && s.interpolate) content = expandWord(this, content);
        if (s.mode === 'heredoc-tabs') {
          content = content.split('\n').map(l => l.replace(/^\t+/, '')).join('\n');
          if (s.interpolate) content = expandWord(this, content);
        }
        this.fdTargets[fd] = { kind: 'string', content };
        // A NEW redirect with string content must start a FRESH read
        // cursor: the read builtin caches its line position in readBufs
        // keyed by content, so a second `<<< "$x"` (or heredoc) with the
        // same text would otherwise resume mid-string (the while-read
        // inside the first redirect consumed lines). The cursor belongs
        // to the redirect's lifetime — re-establishing the fd resets it.
        this.readBufs.delete('s:' + content);
      } else if (s.mode === 'r' || s.mode === 'r+') {
        const target = expandWord(this, String(s.target));
        if (check && !fs.existsSync(target)) {
          emitErr(this, `bash: ${target}: No such file or directory\n`);
          this.lastExit = 1;
          return false;
        }
        this.fdTargets[fd] = { kind: 'file', target, readMode: true };
      } else if (s.mode === 'w' || s.mode === 'a' || s.mode === 'wc') {
        const t = expandWord(this, String(s.target));
        // `>/dev/null` (and `2>/dev/null`): the corpus's most common
        // write redirect — a char device that discards everything, so a
        // `{kind:'discard'}` target skips the per-write open/write syscall
        // (writeFileSync to /dev/null) AND the existence check.
        // ASSUMPTION (option-gated, default ON): SH2_ASSUME_DEVNULL=0
        // restores the file-target path — the standard /dev/null discard
        // device is present and writable (the corpus env's /dev/null is
        // the kernel char device, never a replaced regular file; a write
        // to it can never fail, so the discard's silent success matches
        // GNU's status-0 behavior).
        if (t === '/dev/null' && process.env.SH2_ASSUME_DEVNULL !== '0') {
          this.fdTargets[fd] = { kind: 'discard' };
          continue;
        }
        // The persistent-restore pass creates the file if missing (the
        // original restore loop did; the live install defers creation to
        // the writer or `_ensureRedirectFiles`).
        if (!check && !fs.existsSync(t)) {
          try { fs.closeSync(fs.openSync(t, 'w')); } catch { /* unwritable target: bash reports, we ignore */ }
        }
        // bash opens the target EAGERLY at redirect-install time: an
        // unwritable target skips the command entirely with status 1
        // (`cat - > unwritable` with NO stdin still fails in bash — the
        // open precedes the command; the lazy first-write open would
        // silently succeed for a write-free command — the cat-dash-stdin
        // corpus test's /tmp/out.txt permission collision exposed it).
        // The eager open also truncates an existing file at install time
        // (bash's `> f` semantics — the writer's 'w' mode truncates at
        // first write anyway). Mirror of the r-mode's live-install
        // existence check (check=true only — the persistent-restore pass
        // keeps its create-if-missing and never fails the status).
        if (check) {
          try {
            fs.closeSync(fs.openSync(t, s.mode === 'a' ? 'a' : 'w'));
          } catch (e) {
            emitErr(
              this,
              `bash: ${t}: ${e.code === 'EACCES' ? 'Permission denied' : e.code}\n`
            );
            this.lastExit = 1;
            return false;
          }
        }
        // `wc` is the `>|` clobber-output mode — same open as `w` for the
        // JS runtime (noclobber is a shell-level concept; Node fs is always
        // clobber), so normalize before the flag reaches writeFileSync.
        this.fdTargets[fd] = { kind: 'file', target: t, mode: s.mode === 'wc' ? 'w' : s.mode };
      } else {
        throw new Error(`redirect: unknown mode ${s.mode}`);
      }
    }
    return true;
  },

  // Standalone redirect (`>file` with no command): bash creates the
  // (empty) file even when nothing writes to it. fd-dup (`&N`) and
  // close (`-` / `&-`) targets are NOT files — bash's `echo hi 2>&1`
  // creates nothing (the dup is an fd-table operation, the close
  // closes one) — so skip them exactly like _applyRedirectSpecs does.
  // (Without the skip, an fd-dup spec in the program created a stray
  // empty `&1` file in the gate's CWD — spotted 2026-08-14 when the
  // powershell-sh-go t19 merging-redirection gate run left
  // frontends/powershell-sh-go/&1 behind; the workspace root and
  // sh2perl/ already carried the same litter.)
  _ensureRedirectFiles(specs) {
    for (const s of specs) {
      if (s.mode === 'w' || s.mode === 'a' || s.mode === 'wc') {
        const t = expandWord(this, String(s.target));
        if (/^&\d+$/.test(t) || t === '&-' || t === '-') continue;
        if (!fs.existsSync(t)) {
          try { fs.closeSync(fs.openSync(t, 'w')); } catch { /* unwritable target: bash reports, we ignore */ }
        }
      }
    }
  },

  async redirect(fn, specs = []) {
    const saved = { ...this.fdTargets };
    const persistent = specs.filter(s => s.persist);
    try {
      if (!this._applyRedirectSpecs(specs, saved, true)) return false;
      await fn();
      this._ensureRedirectFiles(specs);
      return this.lastExit === 0;
    } finally {
      // Restore the pre-redirect fd table...
      this.fdTargets = saved;
      // ...but `exec N>f` / `exec N>&M` (exec with no command) redirects
      // persist permanently — bash installs them in the shell's own fd
      // table (`exec 3>&1` then `cmd >&3` later must keep working).
      this._applyRedirectSpecs(persistent, saved, false);
    }
  },

  // Sync twin of redirect for PROVABLY-AWAIT-FREE bodies (see
  // captureSync): the exact same spec install, body run, standalone-file
  // creation, restore + persist logic — minus the await. An await-free
  // body runs to completion synchronously, so no background microtask can
  // observe the mid-redirect fd table (bash: the redirect is installed
  // before the command forks, so background jobs never see it either).
  redirectSync(fn, specs = []) {
    const saved = { ...this.fdTargets };
    const persistent = specs.filter(s => s.persist);
    try {
      if (!this._applyRedirectSpecs(specs, saved, true)) return false;
      fn();
      this._ensureRedirectFiles(specs);
      return this.lastExit === 0;
    } finally {
      this.fdTargets = saved;
      this._applyRedirectSpecs(persistent, saved, false);
    }
  },

  // ── pipelines ──────────────────────────────────────────────────────
  async pipeline(stages) {
    const saved = { ...this.fdTargets };
    let prev = null;
    const statuses = [];
    try {
      for (let i = 0; i < stages.length; i++) {
        if (typeof stages[i] !== 'function') {
          // String stage — the emitter's `echo ARGS | ...` collapse (see
          // src/shir.rs try_echo_stage_text): the stage expression is a
          // sequence `(sh2.lastExit = 0, text)` holding the EXACT bytes
          // the echo builtin would write into the pipe (join + trailing
          // newline unless -n). The produced text IS the stage's output;
          // no fd juggling, no builtin dispatch. Only non-last stages
          // collapse (the last stage must write through the current
          // fd-1 sink — emit — which only the arrow form does).
          prev = String(stages[i] ?? '');
          statuses.push(this.lastExit);
          continue;
        }
        if (i > 0 && prev !== null) this.fdTargets[0] = { kind: 'string', content: prev };
        else if (i === 0) this.fdTargets[0] = saved[0];
        if (i < stages.length - 1) this.fdTargets[1] = { kind: 'capture', buf: '' };
        else this.fdTargets[1] = saved[1];
        await stages[i]();
        statuses.push(this.lastExit);
        const cap = this.fdTargets[1];
        prev = cap && cap.kind === 'capture' ? cap.buf : null;
      }
      this.pipeStatuses = statuses;
      return this.lastExit === 0;
    } finally {
      this.fdTargets = saved;
    }
  },

  // Sync twin of pipeline for PROVABLY-AWAIT-FREE stages (same verdict
  // and semantics as captureSync above): identical fd0/fd1 swaps, string
  // stages, lastExit protocol — minus the per-stage await. The stages run
  // to completion synchronously; an await-free stage cannot yield, so no
  // background job can interleave mid-pipeline (the async form's awaits
  // allowed exactly that — this is closer to bash's sequential pipes).
  pipelineSync(stages) {
    const saved = { ...this.fdTargets };
    let prev = null;
    const statuses = [];
    try {
      for (let i = 0; i < stages.length; i++) {
        if (typeof stages[i] !== 'function') {
          prev = String(stages[i] ?? '');
          statuses.push(this.lastExit);
          continue;
        }
        if (i > 0 && prev !== null) this.fdTargets[0] = { kind: 'string', content: prev };
        else if (i === 0) this.fdTargets[0] = saved[0];
        if (i < stages.length - 1) this.fdTargets[1] = { kind: 'capture', buf: '' };
        else this.fdTargets[1] = saved[1];
        stages[i]();
        statuses.push(this.lastExit);
        const cap = this.fdTargets[1];
        prev = cap && cap.kind === 'capture' ? cap.buf : null;
      }
      this.pipeStatuses = statuses;
      return this.lastExit === 0;
    } finally {
      this.fdTargets = saved;
    }
  },

  // ── case ───────────────────────────────────────────────────────────
  caseMatch(value, patterns) {
    const v = String(value ?? '');
    const ci = this.shoptState.get('nocasematch');
    for (const p of patterns) {
      // command substitution / expansion inside a pattern (`$(_f "$x")`)
      const pat = expandWord(this, runCmdSubst(String(p)));
      if (globMatch(String(pat), ci ? v.toLowerCase() : v)) return p;
    }
    return undefined;
  },

  // ── functions ──────────────────────────────────────────────────────
  define(name, fn) {
    this.functions.set(name, fn);
    return true;
  },

  // ── loops ──────────────────────────────────────────────────────────
  // substring test for the lifted `echo X | grep P >/dev/null 2>/dev/null`
  // idiom: grep's exit status with both streams discarded is exactly "does
  // the line contain the literal pattern", and `echo X` emits one line.
  // Sync, no I/O (the emitter only lifts literal patterns — see src/shir.rs
  // try_lift_grep_contains).
  contains(haystack, needle) {
    return String(haystack ?? '').includes(String(needle ?? ''));
  },

  // Runtime type dispatch for typed frontends (core request
  // go-sh-20260813-154009 — Go's `switch v := x.(type)`): the A1 store is
  // untyped (strings), but LIFTED bindings hold native JS values (numbers
  // for Int-typed vars, booleans, arrays). `typeOf` inspects the actual
  // JS runtime value — typeof + Array.isArray — and returns the A1 type-
  // name vocabulary ("string", "int", "float", "bool", "array", plus
  // the JS typeof fallback for anything else). Store values are always
  // strings → "string", so a frontend that keeps everything in the store
  // (the minimal `var x any = "hi"` case) dispatches on the stored text.
  // `isType(v, name)` is the type-assertion test twin (`sh2.isType(x,
  // "int")`), so `Case`-pattern comparisons can test either shape.
  typeOf(value) {
    if (Array.isArray(value)) return 'array';
    // OBJECT REFS carry their declared type: obj#N -> the struct's name
    // (StrE, LitStr, …), list#N -> 'array'. Named-type assertions
    // (`x.(*StrE)`) dispatch on this vocabulary.
    if (typeof value === 'string' && this._objStore) {
      const o = /^((?:obj|map|list)#)/.test(value) ? this._objStore.get(value) : null;
      if (o) {
        if (o.kind === 'struct') return String(o.type ?? 'struct');
        if (o.kind === 'list') return 'array';
        if (o.kind === 'map') return 'map';
      }
    }
    const t = typeof value;
    if (t === 'number') return Number.isInteger(value) ? 'int' : 'float';
    if (t === 'boolean') return 'bool';
    if (t === 'string') return 'string';
    return t; // 'object', 'undefined', 'bigint', 'function', ...
  },

  isType(value, name) {
    return this.typeOf(value) === String(name ?? '');
  },

  // ── channels / select (core requests go-sh-commclause / ────────────
  // go-sh-recvstmt): the A1 channel vocabulary for the go-sh frontend's
  // `select`/`commClause`/`recvStmt`/`sendStmt` lowerings. A channel is a
  // FIFO object `{ q: [...] }`; makeChan creates one, send pushes, recv
  // shifts. v1 semantics are the NON-BLOCKING poll: recv on an empty
  // channel returns undefined immediately (a Go recv outside a select
  // would block — the frontend should only emit bare recv where a
  // producer provably ran first), and `select` runs the FIRST ready comm
  // clause in source order (recv ready = FIFO non-empty; send ready =
  // FIFO open — always true while the channel is open), else the
  // `default` body when present (Go: a select with no ready clause and
  // no default BLOCKS — the non-blocking poll cannot express that; every
  // corpus-reachable form has a default). The clause bodies are async
  // arrows; the recv target binds via setVar.
  // Channels are HANDLE STRINGS in the A1 store (the store is
  // string-typed): makeChan allocates a handle, registers the FIFO in
  // `this.chans`, and returns the handle; recv/send/select resolve it.
  // The handle survives setVar round-trips (the go-sh frontend stores
  // `ch := make(chan int)` as a plain setVar).
  makeChan() {
    const id = `__chan${++this._chanSeq}`;
    this.chans.set(id, { q: [] });
    return id;
  },
  recv(ch) {
    const c = this.chans.get(String(ch));
    return c && c.q.length ? c.q.shift() : undefined;
  },
  send(ch, v) {
    const c = this.chans.get(String(ch));
    if (c) c.q.push(v);
    return true;
  },
  async select(clauses) {
    const list = clauses ?? [];
    for (const c of list) {
      if (!c) continue;
      const chan = c.ch == null ? null : this.chans.get(String(c.ch));
      if (c.comm === 'recv' && chan && chan.q.length) {
        const v = chan.q.shift();
        if (c.target) this.setVar(c.target, v);
        if (c.body) await c.body();
        return;
      }
      if (c.comm === 'send' && chan) {
        chan.q.push(c.value);
        if (c.body) await c.body();
        return;
      }
    }
    const def = list.find((c) => c && c.comm === 'default');
    if (def && def.body) await def.body();
  },

  // The `echo ARGS | grep [FLAGS] PAT` pipeline lift (see src/shir.rs
  // try_native_echo_grep): a SYNC mini-grep over the echoed text with
  // exact GNU grep semantics for the supported flag set (v/i/n/c/o/q/x
  // incl. combined shorts, -A/-B/-C/-m with integer values, -e/-E/-F,
  // `--`), replacing the async pipeline machinery + the grep subprocess
  // spawn with ONE call. The emitter only lifts provably-static argv
  // (every arg a literal, flags/pattern count within this grammar, no
  // FILE operands, no GNU-extension escapes) — anything else stays on the
  // runtime pipeline, so an unhandled shape here is an emitter bug, not a
  // script error (fail loudly).
  //
  // The helper emits the filtered output through the CURRENT fd-1 sink
  // (module stdout / capture buffer / redirect target — where the
  // pipeline's last stage would write) and records `sh2.lastExit` (grep's
  // exit status: 0 iff any line was selected, even under `-c` with a zero
  // count). With captureMode true the output text is returned instead of
  // emitted (the emitter wraps it in sh2.trimCapture for `$(...)`).
  // grepMatches(text, pattern, flags) — the `grep -o` lift (the A1
  // generic op): the array of matched substrings, one per line (grep
  // -o's output). flags: "E" (ERE as-is), "F" (fixed string), "i"
  // (case-insensitive); the default is BRE (translated). lastExit = 0
  // iff any match; the matches are emitted to the current fd-1 sink
  // (statement context) and returned (value/capture contexts).
  grepMatches(text, pattern, flags) {
    const s = String(text ?? '');
    const fl = String(flags ?? '');
    let body = String(pattern ?? '');
    try {
      if (fl.includes('F')) {
        body = escapeRe(body);
      } else if (!fl.includes('E')) {
        // The shared BRE translator: `\+` → `+`, `\(` → `(`, bare
        // `+ ? | ( ) { }` stay literals (GNU BRE), POSIX classes
        // translate. (The old inline `.replace(/\\+/g, '+')` matched
        // the backslash ALONE and produced `++` — an invalid regex that
        // made `grep -o 'pattern[0-9]\+'` return nothing with exit 2.)
        body = breToJs(body);
      }
      const re = new RegExp(body, fl.includes('i') ? 'gi' : 'g');
      const matches = s.match(re) || [];
      this.lastExit = matches.length > 0 ? 0 : 1;
      const out = matches.join('\n');   // grep -o: one match per line
      // The emitter's capture context (`matched=$(echo X | grep -o P)`
      // → `sh2.captureSync(() => sh2.grepMatches(...))`) reads the fd-1
      // buffer — write the matches into it. The value/statement contexts
      // (a direct `process.stdout.write(String(sh2.grepMatches(...)))`)
      // use the RETURN value, so emitting only into a capture avoids
      // double-printing there.
      if (this.fdTargets[1] && this.fdTargets[1].kind === 'capture') {
        this.fdTargets[1].buf += out;
      }
      return out;
    } catch {
      this.lastExit = 2;
      return [];
    }
  },

  // regexMatch(re, value) — the fish `string match -rq` lift (the A1
  // `Regex` node in condition position, core request
  // fish-sh-go-20260813-192709): the emitter renders the pattern as a
  // JS regex literal, so `re` arrives as a native RegExp OBJECT — the
  // one runtime entry point that consumes a rendered regex literal.
  // ERE search semantics, status 0 iff any match — the same decision
  // the `=~` family records (evalTest's `new RegExp(r).test(l)`), minus
  // the test-string round-trip. A non-RegExp `re` (a bad emit) fails
  // like an invalid pattern (status 2).
  regexMatch(re, value) {
    try {
      const ok = re instanceof RegExp ? re.test(String(value ?? '')) : false;
      this.lastExit = ok ? 0 : 1;
      return ok;
    } catch {
      this.lastExit = 2;
      return false;
    }
  },

  grepText(text, args, captureMode) {
    const s = String(text ?? '');
    const { opts, patterns } = parseGrepArgs(args, false);
    const { matchRe, gRe } = grepRegexes(opts, patterns);
    const out = [];
    const selected = grepSelect(out, s, opts, matchRe, gRe, '', opts.byteOffset, opts.color);
    const matched = selected > 0;
    this.lastExit = matched ? 0 : 1;
    if (captureMode) return out.join('');
    if (out.length > 0) emit(this, out.join(''));
    return matched;
  },

  // cutText(text, args, captureMode) — the sync twin of the cut builtin
  // for the emitter's `echo X | cut OP` fast path (src/shir.rs
  // try_native_echo_cut): the pipeline's fd-1 write + exit status are
  // the helper's emit + lastExit, so the async pipeline machinery
  // disappears. The text is the FULL cut stdin (echo's output — the
  // emitter appends the trailing newline unless `-n`), the args are the
  // statically-validated cut options; the per-line selection is the
  // builtin's exact algorithm (parseCutList/cutPositions, the -s line
  // drop, the trailing-newline rule). cut exits 0 on the lifted shapes,
  // so lastExit = 0 and the return is truthy (&&/||/if contexts branch
  // like the real pipeline). Emits through the CURRENT fd-1 sink
  // (module stdout, capture buffer, redirect target) — exactly where
  // the pipeline's last stage would write.
  cutText(text, args, captureMode) {
    const s = String(text ?? '');
    let delim = '\t';
    let mode = null; // 'f' | 'c' | 'b'
    let pos = null;
    let suppress = false;
    let outDelim = null;
    for (let i = 0; i < args.length; i++) {
      const a = String(args[i]);
      if (a === '--output-delimiter') { outDelim = String(args[++i] ?? ''); continue; }
      if (a.startsWith('--output-delimiter=')) { outDelim = a.slice('--output-delimiter='.length); continue; }
      if (a === '-s') { suppress = true; continue; }
      if (a === '-d') { delim = String(args[++i] ?? '')[0] || '\t'; continue; }
      if (a.startsWith('-d') && a.length > 2) { delim = a[2]; continue; }
      if (a === '-f' || a === '-c' || a === '-b') { mode = a[1]; pos = parseCutList(args[++i]); if (pos === null) { throw new Error(`cutText: invalid field/character list '${args[i]}'`); } continue; }
      if (a.length > 2 && (a[1] === 'f' || a[1] === 'c' || a[1] === 'b')) {
        mode = a[1]; pos = parseCutList(a.slice(2));
        if (pos === null) { throw new Error(`cutText: invalid field/character list '${a.slice(2)}'`); }
        continue;
      }
      throw new Error(`cutText: unsupported arg ${a}`);
    }
    if (mode === null) throw new Error('cutText: no -f/-c/-b list');
    const joinDelim = outDelim !== null ? outDelim : delim;
    const endsNL = s.endsWith('\n');
    const lines = s.split('\n');
    if (endsNL) lines.pop(); // drop the split's trailing '' element
    const out = [];
    for (let li = 0; li < lines.length; li++) {
      const line = lines[li];
      let sel;
      if (mode === 'f') {
        if (!line.includes(delim)) { if (suppress) continue; sel = line; }
        else {
          const fields = line.split(delim);
          const picked = [];
          for (const p of cutPositions(pos, fields.length)) picked.push(fields[p - 1]);
          sel = picked.join(joinDelim);
        }
      } else {
        const chars = [...line];
        const picked = [];
        for (const p of cutPositions(pos, chars.length)) picked.push(chars[p - 1]);
        sel = picked.join('');
      }
      out.push(sel);
    }
    if (endsNL) out.push(''); // GNU emits the final newline even when the last line selected nothing
    const outText = out.join('\n');
    this.lastExit = 0;
    if (captureMode) return outText;
    if (outText.length > 0) emit(this, outText);
    return true;
  },

  async forLoop(items, bodyFn) {
    // Glob-expand any GLOB_MAGIC item (including elements of brace/array
    // results, which arrive as magic-prefixed strings inside arrays).
    const expandItem = (x) => {
      if (typeof x === 'string' && x.startsWith(GLOB_MAGIC)) {
        const pat = x.slice(GLOB_MAGIC.length);
        const hits = globExpand(pat);
        return hits.length > 0 ? hits : [pat]; // no match: keep the pattern (nullglob off)
      }
      return [x];
    };
    const flat = [];
    for (const it of items) {
      if (Array.isArray(it)) for (const x of it) flat.push(...expandItem(x));
      else flat.push(...expandItem(it));
    }
    // bash: the loop's exit status is the last body command's status (or
    // 0 if the body never ran — including a BREAK on the first iteration
    // boundary and the capture bound). The body's own statements record
    // lastExit, so snapshot it after each iteration (mirror of the
    // whileLoop bodyLastExit discipline).
    let bodyLastExit = 0;
    let ran = false;
    for (const v of flat) {
      if (this._capExceeded()) break; // bound infinite producers in a capture
      ran = true;
      try {
        await bodyFn(v);
      } catch (e) {
        // bash: break/continue terminate the iteration with STATUS 0 (the
        // loop's exit status rule — "last command executed in the body" —
        // treats the control-flow keyword itself as the last command,
        // whose status is 0: `for i in 1; do false || continue; done; echo
        // $?` → 0).
        if (isSignal(e, 'BREAK')) { bodyLastExit = 0; break; }
        if (isSignal(e, 'CONTINUE')) { bodyLastExit = 0; continue; }
        throw e;
      }
      bodyLastExit = this.lastExit;
    }
    this.lastExit = ran ? bodyLastExit : 0;
    return true;
  },

  // Sync twin of forLoop for the emitter's fast path: a provably-sync loop
  // (iterable + body contain no awaits, hence no I/O) runs without the
  // per-iteration promise/microtask machinery. Semantics are IDENTICAL
  // (flattening, GLOB_MAGIC expansion, BREAK/CONTINUE/RETURN signals,
  // capture bound) — only the awaits are dropped. Pure CPU, so it never
  // blocks the event loop on I/O; the structural gate whitelists it
  // explicitly (see estree_gate.pl).
  forLoopSync(items, bodyFn) {
    const expandItem = (x) => {
      if (typeof x === 'string' && x.startsWith(GLOB_MAGIC)) {
        const pat = x.slice(GLOB_MAGIC.length);
        const hits = globExpand(pat);
        return hits.length > 0 ? hits : [pat];
      }
      return [x];
    };
    const flat = [];
    for (const it of items) {
      if (Array.isArray(it)) for (const x of it) flat.push(...expandItem(x));
      else flat.push(...expandItem(it));
    }
    // Same bodyLastExit discipline as the async twin (bash: the loop's
    // status is the last body command's status, or 0 if the body never
    // ran).
    let bodyLastExit = 0;
    let ran = false;
    for (const v of flat) {
      if (this._capExceeded()) break;
      ran = true;
      try {
        bodyFn(v);
      } catch (e) {
        // bash: break/continue terminate the iteration with STATUS 0 (the
        // loop's exit status rule — "last command executed in the body" —
        // treats the control-flow keyword itself as the last command,
        // whose status is 0: `for i in 1; do false || continue; done; echo
        // $?` → 0).
        if (isSignal(e, 'BREAK')) { bodyLastExit = 0; break; }
        if (isSignal(e, 'CONTINUE')) { bodyLastExit = 0; continue; }
        throw e;
      }
      bodyLastExit = this.lastExit;
    }
    this.lastExit = ran ? bodyLastExit : 0;
    return true;
  },

  // Checkpointed twin of forLoopSync (the sync-ok-loops transform's
  // `batch_ok` verdict): a loop whose body is sync-executable but that
  // still cannot run as ONE blocking chunk (async region / glob iterable /
  // signals) runs as sync chunks of `batch` iterations with a setImmediate
  // yield between chunks — bash's output order and the capture bound
  // preserved, at ~1/batch of the async forLoop's per-iteration await
  // cost. Semantics mirror forLoopSync EXACTLY (flatten, GLOB_MAGIC,
  // BREAK/CONTINUE/RETURN signals, _capExceeded) — only the yield cadence
  // differs. Await-legal contexts only (the emitter gates it).
  async forLoopBatch(items, bodyFn, batch) {
    const expandItem = (x) => {
      if (typeof x === 'string' && x.startsWith(GLOB_MAGIC)) {
        const pat = x.slice(GLOB_MAGIC.length);
        const hits = globExpand(pat);
        return hits.length > 0 ? hits : [pat];
      }
      return [x];
    };
    const flat = [];
    for (const it of items) {
      if (Array.isArray(it)) for (const x of it) flat.push(...expandItem(x));
      else flat.push(...expandItem(it));
    }
    let n = 0;
    for (const v of flat) {
      if (this._capExceeded()) break;
      if (++n === batch) {
        n = 0;
        await new Promise((r) => setImmediate(r));
      }
      try {
        bodyFn(v);
      } catch (e) {
        if (isSignal(e, 'BREAK')) break;
        if (isSignal(e, 'CONTINUE')) continue;
        throw e;
      }
    }
    return true;
  },

  // ── generic struct/list/map objects (the A1's reference-type store) ──
  // Reference semantics for frontends whose source language has structs,
  // slices and maps BY REFERENCE (Go *T, Zig, Java objects). An object is
  // an opaque ID string riding the normal value channels (vars, 
… [pir] output truncated

		fnSig:       map[string][2]string{},
		fnParams:    map[string]bool{},
		fnParamOrd:  []string{},
		fnLocals:    map[string]bool{},
		paramTypes:  map[string]string{},
		regexpVars:  map[string]string{},
		paramSlice:  map[string]bool{},
	}
	p.prescanFuncNames()

	stmts, err := p.run()
	if err != nil {
		fmt.Fprintln(os.Stderr, "PARSE ERROR:", err)
		return nil, err
	}
	prog := &shiremit.Program{Stmts: stmts}
	return shiremit.Emit(prog)
}

// run drives the parser with panic-based error recovery.
func (p *parser) run() (stmts []map[string]any, err error) {
	defer func() {
		if r := recover(); r != nil {
			if os.Getenv("PANICSTACK") != "" {
				debug.PrintStack()
			}
			fmt.Fprintln(os.Stderr, "PANIC:", r)
			err = fmt.Errorf("%v", r)
		}
	}()
	return p.parseTopLevel(), nil
}

// Package shiremit builds and emits the A1 shIR JSON contract.
//
// The contract is defined in sh2perl/src/shir_json.rs (and the matching
// deserializer in shir_json_in.rs). This Go package is the
// single-source-of-truth for the A1 JSON shape used by all
// ANTLR4+Go frontends (py-sh-go, posix-sh-go, perl-sh-go, go-sh).
// It replaces the deferred #4 serde-derive refactor (in Rust) with
// the equivalent in Go: one Emitter, one Program type, one JSON shape.
//
// The emitted JSON MUST be byte-identical to the core's
// shir_json.rs output for the same program. encoding/json on
// map[string]any produces alphabetically-sorted keys (matching
// serde_json's BTreeMap), which is what the contract requires.
//
// Usage:
//
//	prog := &shiremit.Program{...}
//	b, err := shiremit.Emit(prog)
//	// b is the A1 JSON, ready to write to stdout or feed to
//	// debashc --shir-in-estree for the round-trip / ingress test.
package shiremit

import (
	"encoding/json"
	"sort"
)

// ContractVersion must match sh2perl/src/shir_json.rs CONTRACT_VERSION.
const ContractVersion = 1

// Program is the top-level A1 shIR program.
//
// The JSON field order is alphabetical (encoding/json sorts map keys).
// The struct fields below are exported for programmatic construction;
// the emitted JSON is a map[string]any (sorted), not a Go struct
// literal, so the JSON shape is the contract — not these struct tags.
type Program struct {
	Imports   []string            `json:"imports"`
	Requires  []string            `json:"requires"`
	VarTypes  []VarType           `json:"var_types"`
	Subs      []Sub               `json:"subs"`
	Stmts     []map[string]any    `json:"stmts"`
	ContractVersion int           `json:"contract_version"`
	Type      string              `json:"type"` // always "Program"
}

type VarType struct {
	Name string `json:"name"`
	Type string `json:"type"` // "Int" or "Str"
}

type Sub struct {
	Type   string           `json:"type"` // "Sub"
	Name   string           `json:"name"`
	Params []string         `json:"params"`
	Body   []map[string]any `json:"body"`
}

// Emit serializes prog to the A1 shIR JSON, byte-equivalent to the
// core's shir_json.rs output for the same program (sorted keys,
// contract_version field, etc.).
func Emit(prog *Program) ([]byte, error) {
	// Build the top-level map (sorted by encoding/json).
	// We use map[string]any so keys sort alphabetically on marshal.
	// Empty (non-nil) slices ensure "[]" not "null" in the JSON, matching
	// the contract exactly.
	imports := prog.Imports
	if imports == nil {
		imports = []string{}
	}
	requires := prog.Requires
	if requires == nil {
		requires = []string{}
	}
	v := map[string]any{
		"type":             "Program",
		"contract_version": ContractVersion,
		"imports":          imports,
		"requires":         requires,
		"var_types":        toAnySlice(prog.VarTypes),
		"subs":             toAnySubs(prog.Subs),
		"stmts":            toAnyStmts(prog.Stmts),
	}
	return json.Marshal(v)
}

// EmitToMap returns the program as a map[string]any (sorted keys when
// later marshaled). Useful for tests that need the JSON shape without
// the final marshal step.
func EmitToMap(prog *Program) map[string]any {
	imports := prog.Imports
	if imports == nil {
		imports = []string{}
	}
	requires := prog.Requires
	if requires == nil {
		requires = []string{}
	}
	return map[string]any{
		"type":             "Program",
		"contract_version": ContractVersion,
		"imports":          imports,
		"requires":         requires,
		"var_types":        toAnySlice(prog.VarTypes),
		"subs":             toAnySubs(prog.Subs),
		"stmts":            toAnyStmts(prog.Stmts),
	}
}

// --- helpers to convert typed slices to map slices (so the emitted
// JSON has alphabetically-sorted keys via map[string]any) ---

func toAnySlice(vs []VarType) []any {
	out := make([]any, len(vs))
	for i, v := range vs {
		out[i] = map[string]any{"name": v.Name, "type": v.Type}
	}
	return out
}

func toAnySubs(subs []Sub) []any {
	out := make([]any, len(subs))
	for i, s := range subs {
		out[i] = map[string]any{
			"type":   s.Type,
			"name":   s.Name,
			"params": s.Params,
			"body":   toAnyStmts(s.Body),
		}
	}
	return out
}

func toAnyStmts(stmts []map[string]any) []any {
	out := make([]any, len(stmts))
	for i, s := range stmts {
		out[i] = s
	}
	return out
}

// SortedKeys returns the keys of m in alphabetical order (for callers
// that need to inspect the JSON shape).
func SortedKeys(m map[string]any) []string {
	keys := make([]string, 0, len(m))
	for k := range m {
		keys = append(keys, k)
	}
	sort.Strings(keys)
	return keys
}

// go-sh CLI: Go source -> A1 shIR JSON (thin wrapper around the golib
// library, which the combined busybox also dispatches through).
//
// PACKAGE MODE: Go packages span multiple FILES (`cpp-sh-go/main.go` +
// `cpp-sh-go/parser.go` share `package cppshgo`; main.go calls
// parser.go's treeCheck). The frontend resolves cross-file references
// via its name prescan, so multiple --shir inputs (or a directory of
// .go files, _test.go excluded) are CONCATENATED in input order before
// parsing — the same source a go build would see.
package main

import (
	"fmt"
	"os"
	"path/filepath"
	"strings"

	golib "github.com/gmatht/sh2loop/frontends/go-sh"
)

func main() {
	args := os.Args[1:]
	raw := false
	filtered := []string{}
	for _, a := range args {
		if a == "--raw" {
			raw = true
		} else {
			filtered = append(filtered, a)
		}
	}
	if len(filtered) < 2 || filtered[0] != "--shir" {
		fmt.Fprintln(os.Stderr, "usage: go-sh --shir <file.go> [more.go | dir] [--raw]")
		os.Exit(2)
	}
	var parts []string
	for _, inp := range filtered[1:] {
		if info, err := os.Stat(inp); err == nil && info.IsDir() {
			entries, err2 := os.ReadDir(inp)
			if err2 != nil {
				fmt.Fprintln(os.Stderr, "go-sh: "+err2.Error())
				os.Exit(2)
			}
			for _, e := range entries {
				name := e.Name()
				if e.IsDir() || !strings.HasSuffix(name, ".go") || strings.HasSuffix(name, "_test.go") {
					continue
				}
				b, err3 := os.ReadFile(filepath.Join(inp, name))
				if err3 != nil {
					fmt.Fprintln(os.Stderr, "go-sh: "+err3.Error())
					os.Exit(2)
				}
				parts = append(parts, string(b))
			}
			continue
		}
		b, err := os.ReadFile(inp)
		if err != nil {
			// preserve the legacy behavior: a non-readable operand is
			// the SOURCE TEXT itself (`go-sh --shir 'package main...'`)
			parts = append(parts, inp)
			continue
		}
		parts = append(parts, string(b))
	}
	src := strings.Join(parts, "\n")
	out, err := golib.Shir(src)
	if err != nil {
		fmt.Fprintln(os.Stderr, "go-sh: "+err.Error())
		os.Exit(2)
	}
	os.Stdout.Write(out)
	if !raw {
		os.Stdout.Write([]byte{'\n'})
	}
}
