      if (a.startsWith('--output-delimiter=')) { outDelim = a.slice('--output-delimiter='.length); continue; }
      if (a === '-s') { suppress = true; continue; }
      if (a === '-d') { delim = String(args[++i] ?? '')[0] || '\t'; continue; }
      if (a.startsWith('-d') && a.length > 2) { delim = a[2]; continue; }
